const lessons = [
  {"num": 2, "time": "00:00:30,000 --> 00:00:31,760", "arabic": "أَحْمَدُ", "segs": null, "full_uz": "Ahmad!", "note": null},
  {"num": 3, "time": "00:00:31,760 --> 00:00:36,820", "arabic": "كَمَا تَشَاءِينَ يَا أُمَّ أَحْمَدَ", "segs": null, "full_uz": "Qanday xohlasang, Umm Ahmad.", "note": null},
  {"num": 4, "time": "00:00:36,820 --> 00:00:41,960", "arabic": "قَدْ عَرَضَ عَلَيَّ عَمِّي الْعَمَلَ فِي بَيْتِ الْحِكْمَةِ نَسَّاخًا لِلْكُتُبِ", "segs": null, "full_uz": "Amakim menga Baytul-Hikmada kitoblar ko'chiruvchisi bo'lib ishlashni taklif qildi.", "note": "«بَيْتُ الْحِكْمَةِ» — Bag'dodda o'rta asrlarda mavjud bo'lgan mashhur ilm-fan va tarjima markazi."},
  {"num": 5, "time": "00:00:41,960 --> 00:00:50,260", "arabic": "وَطَلَبُكَ الْعِلْمَ؟ وَشَيْخُكَ؟", "segs": null, "full_uz": "Ilm izlashing-chi? Shayxing-chi?", "note": null},
  {"num": 7, "time": "00:00:50,260 --> 00:00:54,060", "arabic": "سَأُوَفِّقُ إِنْ شَاءَ اللَّهُ بَيْنَ الْعَمَلِ وَطَلَبِ الْعِلْمِ", "segs": null, "full_uz": "Alloh xohlasa, ishni ilm izlash bilan muvofiqlashtiraman.", "note": null},
  {"num": 8, "time": "00:00:54,060 --> 00:01:00,419", "arabic": "وَإِنْ لَمْ تَسْتَطِعْ، أَقْصِدُ إِنْ شَغَلَكَ الْعَمَلُ عَنْ طَلَبِ الْعِلْمِ", "segs": null, "full_uz": "Agar uddalay olmasang... ya'ni, agar ish seni ilm izlashdan chalg'itsa.", "note": "«أَقْصِدُ» — gapni to'g'rilash uchun ishlatiladigan ibora, o'zbekcha «ya'ni» ga mos keladi."},
  {"num": 11, "time": "00:01:00,419 --> 00:01:04,060", "arabic": "أَخْبَرْتُ عَمِّي بِذَلِكَ وَوَعَدَنِي بِأَنَّهُ سَيَجِدُ لِي حَلًّا", "segs": null, "full_uz": "Amakimga buni aytdim, u esa menga yechim topib berishga va'da berdi.", "note": null},
  {"num": 13, "time": "00:01:04,060 --> 00:01:14,159", "arabic": "أَنْتَ تَعْرِفُ يَا وَالِدِي أَنَّ طَلَبَكَ الْعِلْمَ لَيْسَ لِي بِهِ الدُّنْيَا وَمَا عَلَيْهَا، وَلَنْ يُضِيمَنَّ اللَّهُ فِي أَرْزَاقِنَا", "segs": [{"ar": "أَنْتَ تَعْرِفُ يَا وَالِدِي أَنَّ طَلَبَكَ الْعِلْمَ", "uz": "Sen bilasan, otajon, sening ilm izlashing"}, {"ar": "لَيْسَ لِي بِهِ الدُّنْيَا وَمَا عَلَيْهَا", "uz": "mening nazarimda dunyo va undagi hamma narsadan qimmatliroq"}, {"ar": "وَلَنْ يُضِيمَنَّ اللَّهُ فِي أَرْزَاقِنَا", "uz": "va Alloh bizni rizqimizda kamsitmaydi"}], "full_uz": "Sen bilasan, otajon, sening ilm izlashing mening nazarimda dunyo va undagi hamma narsadan qimmatliroq, va Alloh bizni rizqimizda kamsitmaydi.", "note": "«لَنْ يُضِيمَنَّ» — «يضيم» (kamsitmoq, adolatsizlik qilmoq) fe'lining muakkad (ta'kidlangan) shakli, nun tavkid bilan."},
  {"num": 17, "time": "00:01:14,159 --> 00:01:21,359", "arabic": "لَكِنْ يَا أُمِّي، نَحْنُ بِحَاجَةٍ لِهَذَا الْمَالِ", "segs": null, "full_uz": "Lekin, onajon, bizga bu pul kerak.", "note": null},
  {"num": 19, "time": "00:01:21,359 --> 00:01:24,459", "arabic": "فَأَنْتَ تَرَيْنَ مَا آلَتْ إِلَيْهِ أَحْوَالُنَا", "segs": null, "full_uz": "Axir, sen bizning ahvolimiz qanday holga kelganini ko'rib turibsan.", "note": null},
  {"num": 20, "time": "00:01:24,459 --> 00:01:32,159", "arabic": "أَنَا أُقَدِّرُ حِرْصَكَ عَلَيَّ يَا وَالِدِي، فَأَنْتَ رَجُلُ الْبَيْتِ وَالْقَيِّمُ عَلَيْهِ", "segs": null, "full_uz": "Men sening menga bo'lgan g'amxo'rligingni qadrlayman, otajon, axir sen bu uyning erkagi va uni boshqaruvchisisan.", "note": null},
  {"num": 22, "time": "00:01:32,159 --> 00:01:43,099", "arabic": "وَغِذَائِي فِي غُدُوِّكَ وَرَوَاحِكَ عِنْدَ شَيْخِكَ، وَقُرَّةُ عَيْنِي فِي حَمْلِكَ الْقَرَاطِيسَ وَالْمِحْبَرَةَ", "segs": [{"ar": "وَغِذَائِي فِي غُدُوِّكَ وَرَوَاحِكَ عِنْدَ شَيْخِكَ", "uz": "mening ozig'im — sening ertayu kech shayxing huzuriga borib-kelishingda"}, {"ar": "وَقُرَّةُ عَيْنِي فِي حَمْلِكَ الْقَرَاطِيسَ وَالْمِحْبَرَةَ", "uz": "ko'zimning nuri esa — qog'oz va siyohdonni ko'tarib yurishingda"}], "full_uz": "Mening ozig'im — sening ertayu kech shayxing huzuriga borib-kelishingda, ko'zimning nuri esa — qog'oz va siyohdonni ko'tarib yurishingda.", "note": "«قُرَّةُ عَيْنِي» — «ko'zimning nuri/quvonchi» ma'nosidagi mashhur arabcha ibora, katta baxt-quvonch keltiruvchi narsani bildiradi."},
  {"num": 24, "time": "00:01:43,099 --> 00:01:50,199", "arabic": "لَا أَدْرِي مَا أَقُولُ لَكَ يَا وَلَدِي", "segs": null, "full_uz": "Senga nima deyishni bilmayapman, o'g'lim.", "note": null},
  {"num": 25, "time": "00:01:52,199 --> 00:01:55,840", "arabic": "وَلَكِنْ فِي صَدْرِي شَيْءٌ مِنْ هَذَا الْعَمَلِ", "segs": null, "full_uz": "Lekin ko'nglimda bu ish haqida bir noxushlik bor.", "note": null},
  {"num": 26, "time": "00:01:55,840 --> 00:02:02,420", "arabic": "وَأَخَافُ أَنْ يَأْخُذَ مِنْكَ وَقْتًا طَوِيلًا فَيَصْرِفَكَ عَنْ طَلَبِ الْعِلْمِ", "segs": null, "full_uz": "Va undan qo'rqamanki, u sening ko'p vaqtingni olib, seni ilm izlashdan chalg'itadi.", "note": null},
  {"num": 28, "time": "00:02:02,420 --> 00:02:09,480", "arabic": "كُونِي عَلَى يَقِينٍ لَنْ أُقَدِّمَ زَائِلًا عَلَى بَاقٍ، وَلَنْ أَبِيعَ الْعِلْمَ بِعَرَضٍ مِنَ الدُّنْيَا", "segs": [{"ar": "كُونِي عَلَى يَقِينٍ لَنْ أُقَدِّمَ زَائِلًا عَلَى بَاقٍ", "uz": "ishonch hosil qil, men o'tkinchini boqiydan ustun qo'ymayman"}, {"ar": "وَلَنْ أَبِيعَ الْعِلْمَ بِعَرَضٍ مِنَ الدُّنْيَا", "uz": "va ilmni dunyoning hech bir matohiga sotmayman"}], "full_uz": "Ishonch hosil qil, men o'tkinchini boqiydan ustun qo'ymayman, va ilmni dunyoning hech bir matohiga sotmayman.", "note": "«زَائِلٌ» (o'tkinchi, dunyoviy) va «بَاقٍ» (boqiy, mangu — ilmga ishora) so'zlari qarama-qarshi qo'yilgan klassik uslub."},
  {"num": 31, "time": "00:02:21,259 --> 00:02:23,300", "arabic": "وَهَذَا مِفْتَاحُ الدُّكَّانِ", "segs": null, "full_uz": "Va mana bu do'kon kaliti.", "note": null},
  {"num": 32, "time": "00:02:23,300 --> 00:02:27,800", "arabic": "مِفْتَاحٌ؟", "segs": null, "full_uz": "Kalitmi?", "note": null},
  {"num": 33, "time": "00:02:27,800 --> 00:02:29,780", "arabic": "مِفْتَاحُ الدُّكَّانِ", "segs": null, "full_uz": "Do'kon kaliti.", "note": null},
  {"num": 34, "time": "00:02:29,780 --> 00:02:31,160", "arabic": "أَجَلْ", "segs": null, "full_uz": "Ha, xo'p.", "note": null},
  {"num": 35, "time": "00:02:31,160 --> 00:02:37,560", "arabic": "تَجْمَعُ النِّعَالَةَ وَالْجُلُودَ وَالصَّمْغَةَ وَالْحِبَالَ وَتَذْهَبُ فِي الصَّبَاحِ", "segs": [{"ar": "تَجْمَعُ النِّعَالَةَ وَالْجُلُودَ وَالصَّمْغَةَ وَالْحِبَالَ", "uz": "na'ldoshlar, teri, elim va arqonlarni yig'ib qo'yasan"}, {"ar": "وَتَذْهَبُ فِي الصَّبَاحِ", "uz": "va ertalab boraverasan"}], "full_uz": "Na'ldoshlar, teri, elim va arqonlarni yig'ib qo'yasan, va ertalab boraverasan.", "note": null},
  {"num": 38, "time": "00:02:37,560 --> 00:02:43,720", "arabic": "وَإِيَّاكَ ثُمَّ إِيَّاكَ ثُمَّ إِيَّاكَ أَنْ أَجِدَكَ نَائِمًا فِي الدُّكَّانِ دُونَ عَمَلٍ", "segs": [{"ar": "وَإِيَّاكَ ثُمَّ إِيَّاكَ ثُمَّ إِيَّاكَ", "uz": "ehtiyot bo'l, yana ehtiyot bo'l, yana ehtiyot bo'l"}, {"ar": "أَنْ أَجِدَكَ نَائِمًا فِي الدُّكَّانِ دُونَ عَمَلٍ", "uz": "seni do'konda ishlamay uxlab yotgan holingda topmayin"}], "full_uz": "Ehtiyot bo'l, yana ehtiyot bo'l, yana ehtiyot bo'l — seni do'konda ishlamay uxlab yotgan holingda topmayin.", "note": "«إِيَّاكَ» — kuchli ogohlantirish uchun ishlatiladigan zamir, «ehtiyot bo'l, saqlan» ma'nosida; uch marta takrorlanishi ta'kidni kuchaytiradi."},
  {"num": 41, "time": "00:02:43,720 --> 00:02:46,200", "arabic": "أَفْتَحُ الدُّكَّانَ", "segs": null, "full_uz": "Do'konni ochaman.", "note": null},
  {"num": 42, "time": "00:02:46,200 --> 00:02:49,380", "arabic": "أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ", "segs": null, "full_uz": "Tongga yetdik, va mulk Allohnikidir.", "note": "Bu — musulmonlarning ertalabki mashhur duosidan bir bo'lak (tongga tong duosi)."},
  {"num": 43, "time": "00:02:49,380 --> 00:02:51,460", "arabic": "وَأَدْخُلُ وَأَعْمَلُ", "segs": null, "full_uz": "Va kirib ishlayman.", "note": null},
  {"num": 44, "time": "00:02:51,460 --> 00:02:56,359", "arabic": "أُمِّي، وَلَكِنْ مِنْ أَيْنَ سَنَدْفَعُ كِرَاءَةَ الدُّكَّانِ؟", "segs": null, "full_uz": "Onajon, lekin do'kon ijarasini qayerdan to'laymiz?", "note": null},
  {"num": 46, "time": "00:02:56,359 --> 00:02:59,399", "arabic": "أَعْطَيْتُ أُمَّ أَحْمَدَ كِرَاءَةَ هَذَا الشَّهْرِ", "segs": null, "full_uz": "Umm Ahmadga shu oyning ijarasini berdim.", "note": null},
  {"num": 47, "time": "00:02:59,399 --> 00:03:01,299", "arabic": "وَالْأَرْزَاقُ بِيَدِ اللَّهِ يَا بُنَيَّ", "segs": null, "full_uz": "Rizqlar esa Allohning qo'lida, o'g'lim.", "note": null},
  {"num": 48, "time": "00:03:01,299 --> 00:03:07,500", "arabic": "أُمِّي أَخْشَى أَنَّنِي لَنْ أَسْتَطِيعَ أَنْ أُحَصِّلَ مَا يَكْفِي", "segs": null, "full_uz": "Onajon, yetarlicha topa olmasligimdan qo'rqaman.", "note": null},
  {"num": 49, "time": "00:03:07,500 --> 00:03:09,519", "arabic": "لَا تَبْدَأْ بِتَذَمُّرِكَ مِنَ الْآنَ", "segs": null, "full_uz": "Hozirdan norozilik bildirishni boshlama.", "note": null},
  {"num": 50, "time": "00:03:09,519 --> 00:03:18,419", "arabic": "بِإِمْكَانِكَ أَنْ تَجْمَعَ الْكَثِيرَ مِنَ الْمَالِ، حِينَهَا نَسْتَطِيعُ أَنْ نَجِدَ لَكَ بِهِ عَرُوسًا جَمِيلَةً", "segs": [{"ar": "بِإِمْكَانِكَ أَنْ تَجْمَعَ الْكَثِيرَ مِنَ الْمَالِ", "uz": "sen ko'p pul yig'ishing mumkin"}, {"ar": "حِينَهَا نَسْتَطِيعُ أَنْ نَجِدَ لَكَ بِهِ عَرُوسًا جَمِيلَةً", "uz": "shunda senga chiroyli kelinchak topib bera olamiz"}], "full_uz": "Sen ko'p pul yig'ishing mumkin, shunda senga chiroyli kelinchak topib bera olamiz.", "note": null},
  {"num": 52, "time": "00:03:18,419 --> 00:03:23,659", "arabic": "عَرُوسٌ؟", "segs": null, "full_uz": "Kelinchakmi?", "note": null},
  {"num": 53, "time": "00:03:23,659 --> 00:03:25,000", "arabic": "أَجَلْ عَرُوسٌ", "segs": null, "full_uz": "Ha, kelinchak.", "note": null},
  {"num": 54, "time": "00:03:25,000 --> 00:03:31,000", "arabic": "أَلَا تَرَى أَنَّ أَتْرَابَكَ قَدْ تَزَوَّجُوا مُنْذُ سِنِينَ، وَأَنْتَ قَدْ تَجَاوَزْتَ الثَّلَاثِينَ وَلَمَّا تَتَزَوَّجْ؟", "segs": [{"ar": "أَلَا تَرَى أَنَّ أَتْرَابَكَ قَدْ تَزَوَّجُوا مُنْذُ سِنِينَ", "uz": "tengdoshlaring necha yildan beri uylanganini ko'rmayapsanmi"}, {"ar": "وَأَنْتَ قَدْ تَجَاوَزْتَ الثَّلَاثِينَ وَلَمَّا تَتَزَوَّجْ؟", "uz": "sen esa o'ttizdan oshding-u, hali uylanmading?"}], "full_uz": "Tengdoshlaring necha yildan beri uylanganini ko'rmayapsanmi? Sen esa o'ttizdan oshding-u, hali uylanmading?", "note": null},
  {"num": 56, "time": "00:03:31,679 --> 00:03:35,799", "arabic": "أَعِدُكِ يَا أُمِّي أَنْ أَصِلَ اللَّيْلَ بِالنَّهَارِ كَيْ أَجْمَعَ صَدَاقَ عَرُوسِي", "segs": null, "full_uz": "Onajon, senga va'da beraman, kelinim mahrini yig'ish uchun kechayu kunduz ishlayman.", "note": "«يَصِلُ اللَّيْلَ بِالنَّهَارِ» — «kechani kunduzga ulamoq», ya'ni tinmay, uzluksiz mehnat qilish ma'nosidagi ibora."},
  {"num": 58, "time": "00:03:35,799 --> 00:03:39,399", "arabic": "أَرَاكَ الْآنَ قَدْ تَرَكْتَ التَّذَمُّرَ بَعْدَ أَنْ سَمِعْتَ بِالْعَرُوسِ", "segs": null, "full_uz": "Endi ko'rib turibmanki, kelinchak haqida eshitgach, norozilik bildirishni tashlab qo'yding.", "note": null},
  {"num": 59, "time": "00:03:39,399 --> 00:03:42,139", "arabic": "وَلَسْتُ أَرَاكَ بِعَنْتَرَ وَلَا هِيَ بِعَبْلَةَ", "segs": null, "full_uz": "Vaholanki, seni Antar deb, uni ham Abla deb bilmayman.", "note": "«عَنْتَرُ» va «عَبْلَةُ» — arab adabiyotidagi mashhur afsonaviy oshiq-ma'shuqlar (Antar va Abla) nomlari, ular ideal sevishganlar timsoli sifatida ishlatiladi."},
  {"num": 60, "time": "00:03:42,139 --> 00:03:44,439", "arabic": "أُمِّي أَعِدُكِ أَنَّنِي لَنْ أَتَذَمَّرَ", "segs": null, "full_uz": "Onajon, senga va'da beraman, norozilik bildirmayman.", "note": null},
  {"num": 61, "time": "00:03:44,439 --> 00:03:45,639", "arabic": "سَنَرَى", "segs": null, "full_uz": "Ko'ramiz.", "note": null},
  {"num": 62, "time": "00:03:45,639 --> 00:03:47,079", "arabic": "سَتَرَيْنَ يَا أُمَّ عَامِرٍ", "segs": null, "full_uz": "Ko'rasan, Umm Omir.", "note": null},
  {"num": 63, "time": "00:03:47,079 --> 00:03:48,319", "arabic": "إِلَى الْعَمَلِ يَا عَامِرُ", "segs": null, "full_uz": "Ishga, Omir.", "note": null},
  {"num": 64, "time": "00:03:48,319 --> 00:03:50,479", "arabic": "إِلَى الدُّكَّانِ، عَرُوسِي", "segs": null, "full_uz": "Do'konga, kelinginam.", "note": null},
  {"num": 65, "time": "00:04:13,979 --> 00:04:15,979", "arabic": "تَبْدُو فَتَاةً طَيِّبَةً", "segs": null, "full_uz": "Yaxshi qizga o'xshaydi.", "note": null},
  {"num": 66, "time": "00:04:15,979 --> 00:04:20,180", "arabic": "كَانَ اللَّهُ فِي عَوْنِهَا", "segs": null, "full_uz": "Alloh unga yordamchi bo'lsin.", "note": null},
  {"num": 67, "time": "00:04:20,180 --> 00:04:27,219", "arabic": "إِنَّهَا طَيِّبَةٌ إِلَى حَدِّ أَنَّهَا تُضِيعُ وَالِدَهَا فِي السُّوقِ كَطِفْلٍ يَخْرُجُ مَعَ وَالِدَيْهِ لِأَوَّلِ مَرَّةٍ", "segs": [{"ar": "إِنَّهَا طَيِّبَةٌ إِلَى حَدِّ أَنَّهَا تُضِيعُ وَالِدَهَا فِي السُّوقِ", "uz": "u shu qadar sodda-yaxshiki, bozorda otasidan adashib qoladi"}, {"ar": "كَطِفْلٍ يَخْرُجُ مَعَ وَالِدَيْهِ لِأَوَّلِ مَرَّةٍ", "uz": "xuddi ota-onasi bilan birinchi marta chiqqan boladek"}], "full_uz": "U shu qadar sodda-yaxshiki, bozorda otasidan adashib qoladi, xuddi ota-onasi bilan birinchi marta chiqqan boladek.", "note": null},
  {"num": 69, "time": "00:04:27,219 --> 00:04:29,399", "arabic": "يَجِبُ أَنْ تُسَاعِدَهَا يَا خَالِدُ", "segs": null, "full_uz": "Unga yordam berishing kerak, Xolid.", "note": null},
  {"num": 70, "time": "00:04:29,399 --> 00:04:34,740", "arabic": "لَنْ آلُوَ مَعَهَا يَا أُمِّي، غَدًا سَأَبْحَثُ فِي السُّوقِ وَأَسْأَلُ الْبَاعَةَ وَالتُّجَّارَ لَعَلَّهُمْ يَعْرِفُونَ وَالِدَهَا", "segs": [{"ar": "لَنْ آلُوَ مَعَهَا يَا أُمِّي", "uz": "unga yordamda hech qanday sa'y-harakatni ayamayman, onajon"}, {"ar": "غَدًا سَأَبْحَثُ فِي السُّوقِ وَأَسْأَلُ الْبَاعَةَ وَالتُّجَّارَ", "uz": "ertaga bozorni izlab, sotuvchi va savdogarlardan so'rayman"}, {"ar": "لَعَلَّهُمْ يَعْرِفُونَ وَالِدَهَا", "uz": "shoyad ular uning otasini bilishar"}], "full_uz": "Unga yordamda hech qanday sa'y-harakatni ayamayman, onajon. Ertaga bozorni izlab, sotuvchi va savdogarlardan so'rayman, shoyad ular uning otasini bilishar.", "note": "«لَا يَأْلُو جُهْدًا» — «hech qanday sa'y-harakatni ayamaslik», ya'ni qo'lidan kelganicha harakat qilish ma'nosidagi ibora."},
  {"num": 73, "time": "00:04:34,740 --> 00:04:42,719", "arabic": "اذْهَبْ إِلَى النُّزُلِ الَّتِي يَنْزِلُ بِهَا الْقَادِمُونَ، وَاسْأَلْ عَنْ قَافِلَةٍ أَتَتِ الْيَوْمَ مِنْ خُرَاسَانَ", "segs": [{"ar": "اذْهَبْ إِلَى النُّزُلِ الَّتِي يَنْزِلُ بِهَا الْقَادِمُونَ", "uz": "kelgan-ketganlar tushadigan mehmonxonaga bor"}, {"ar": "وَاسْأَلْ عَنْ قَافِلَةٍ أَتَتِ الْيَوْمَ مِنْ خُرَاسَانَ", "uz": "va bugun Xurosondan kelgan karvon haqida so'ra"}], "full_uz": "Kelgan-ketganlar tushadigan mehmonxonaga bor va bugun Xurosondan kelgan karvon haqida so'ra.", "note": null},
  {"num": 75, "time": "00:04:42,719 --> 00:04:45,219", "arabic": "هَذَا هُوَ الرَّأْيُ", "segs": null, "full_uz": "Mana shu to'g'ri fikr.", "note": null},
  {"num": 77, "time": "00:04:47,100 --> 00:04:54,660", "arabic": "يَا أُمِّي، الْفَتَاةُ أَمَانَةٌ فِي عُنُقِكِ، فَاحْرِصِي عَلَى أَلَّا تَنَامَ جَائِعَةً", "segs": [{"ar": "يَا أُمِّي، الْفَتَاةُ أَمَانَةٌ فِي عُنُقِكِ", "uz": "onajon, bu qiz sening bo'yningdagi omonat"}, {"ar": "فَاحْرِصِي عَلَى أَلَّا تَنَامَ جَائِعَةً", "uz": "shuning uchun uning och holda uxlab qolmasligiga e'tibor ber"}], "full_uz": "Onajon, bu qiz sening bo'yningdagi omonat, shuning uchun uning och holda uxlab qolmasligiga e'tibor ber.", "note": "«أَمَانَةٌ فِي عُنُقِكَ» — «bo'yningdagi omonat», ya'ni javobgarlik yuklangan narsa ma'nosidagi ibora."},
  {"num": 78, "time": "00:04:54,660 --> 00:04:58,860", "arabic": "إِنَّهَا تَرْفُضُ الْأَكْلَ وَلَكِنَّنِي سَأُحَاوِلُ", "segs": null, "full_uz": "U ovqatlanishdan bosh tortyapti, lekin men harakat qilaman.", "note": null},
  {"num": 79, "time": "00:04:58,860 --> 00:05:01,340", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Sizga salom.", "note": null},
  {"num": 80, "time": "00:05:01,340 --> 00:05:02,660", "arabic": "وَعَلَيْكُمُ السَّلَامُ", "segs": null, "full_uz": "Sizga ham salom.", "note": null},
  {"num": 81, "time": "00:05:15,220 --> 00:05:25,760", "arabic": "سَأَفُكُّ قَيْدَ يَدَيْكِ وَفَمَكِ لِتَأْكُلِي", "segs": null, "full_uz": "Ovqatlanishing uchun qo'llaring va og'zingdagi bog'ni yechib qo'yaman.", "note": null},
  {"num": 82, "time": "00:05:25,760 --> 00:05:29,560", "arabic": "وَإِنْ عُدْتِ لِلصُّرَاخِ سَنَعُودُ لِلْقُيُودِ مِنْ جَدِيدٍ", "segs": null, "full_uz": "Agar yana qichqirishga qaytsang, biz yana kishanlarga qaytamiz.", "note": null},
  {"num": 83, "time": "00:05:29,560 --> 00:05:31,060", "arabic": "فُكَّهَا يَا حَنْظَلَةُ", "segs": null, "full_uz": "Uni yech, Hanzala.", "note": null},
  {"num": 84, "time": "00:05:31,060 --> 00:05:35,600", "arabic": "مَا الَّذِي اقْتَرَفْتُهُ حَتَّى تَفْعَلَ بِي مَا فَعَلْتَ؟", "segs": null, "full_uz": "Menga qilganlaringni qilishing uchun men nima gunoh qildim?", "note": null},
  {"num": 85, "time": "00:05:35,600 --> 00:05:36,840", "arabic": "أَلَا تَخَافِينَ اللَّهَ؟", "segs": null, "full_uz": "Allohdan qo'rqmaysanmi?", "note": null},
  {"num": 86, "time": "00:05:36,840 --> 00:05:39,100", "arabic": "دَعْكِ مِنْ هَذَا الْكَلَامِ الَّذِي لَا طَائِلَ مِنْهُ", "segs": null, "full_uz": "Bu foydasiz gaplarni qo'y.", "note": "«لَا طَائِلَ مِنْهُ» — «foydasi yo'q, behuda» ma'nosidagi ibora."},
  {"num": 87, "time": "00:05:39,100 --> 00:05:42,180", "arabic": "وَكُلِي طَعَامَكِ فَالنَّهَارُ طَوِيلٌ وَالْجُوعُ قَارِسٌ", "segs": null, "full_uz": "Ovqatingni ye, kun uzoq, ochlik esa achchiq.", "note": null},
  {"num": 88, "time": "00:05:42,180 --> 00:05:45,439", "arabic": "لَا حَاجَةَ لِي لِطَعَامِكِ هَذَا", "segs": null, "full_uz": "Menga bu ovqating kerak emas.", "note": null},
  {"num": 89, "time": "00:05:45,439 --> 00:05:53,879", "arabic": "اِسْمَعِي أَيَّتُهَا الْفَتَاةُ، لَنْ تَضُرِّي إِلَّا نَفْسَكِ بِامْتِنَاعِكِ عَنِ الطَّعَامِ", "segs": [{"ar": "اِسْمَعِي أَيَّتُهَا الْفَتَاةُ", "uz": "eshit, qizaloq"}, {"ar": "لَنْ تَضُرِّي إِلَّا نَفْسَكِ بِامْتِنَاعِكِ عَنِ الطَّعَامِ", "uz": "ovqatdan bosh tortishing bilan faqat o'zingga zarar keltirasan"}], "full_uz": "Eshit, qizaloq, ovqatdan bosh tortishing bilan faqat o'zingga zarar keltirasan.", "note": null},
  {"num": 91, "time": "00:05:53,879 --> 00:05:58,139", "arabic": "مِنْ هَذِهِ الدَّارِ لَنْ تَخْرُجِي إِلَّا إِلَى دَارِ سَيِّدِكِ", "segs": null, "full_uz": "Bu uydan faqat xo'jayiningning uyiga chiqasan.", "note": null},
  {"num": 92, "time": "00:05:58,139 --> 00:06:01,860", "arabic": "وَسَوَاءٌ عِنْدِي أَكَلْتِ أَمْ مُتِّ مِنَ الْجُوعِ", "segs": null, "full_uz": "Ovqatlaning yoki ochlikdan o'l — menga farqi yo'q.", "note": null},
  {"num": 93, "time": "00:06:01,860 --> 00:06:05,480", "arabic": "وَمَا أَمْلِكُ لَكِ وَقَدْ نَزَعْتِ مِنْ قَلْبِكِ الرَّحْمَةَ", "segs": null, "full_uz": "Qalbingdan rahmni sug'urib tashlagan bo'lsang, senga qo'limdan nima kelardi.", "note": null},
  {"num": 94, "time": "00:06:05,480 --> 00:06:07,180", "arabic": "أَلَيْسَ فِي قَلْبِكَ ذَرَّةٌ مِنْ شَفَقَةٍ؟", "segs": null, "full_uz": "Qalbingda bir zarracha shafqat yo'qmi?", "note": null},
  {"num": 95, "time": "00:06:08,720 --> 00:06:11,000", "arabic": "ذَرَّةٌ؟ ذَرَّاتٌ", "segs": null, "full_uz": "Zarrachami? Zarrachalar bor.", "note": "«ذَرَّةٌ» (bitta zarracha) va «ذَرَّاتٌ» (zarrachalar, ko'plik) so'zlari bilan o'ynash — javob berayotgan kishi so'zni istehzo bilan ko'plik shaklda qaytaradi."},
  {"num": 96, "time": "00:06:11,000 --> 00:06:23,120", "arabic": "لَوْ لَمْ تَكُنْ لَدَيَّ ذَرَّةٌ مِنْ شَفَقَةٍ لَمَا أَتَيْتُكِ بِالطَّعَامِ رَغْمَ حِدَّةِ لِسَانِكِ، الَّذِي سَأَحْرِصُ عَلَى تَرْوِيضِهِ لِيُصْبِحَ لَائِقًا بِجَارِيَةٍ مُطِيعَةٍ وَجَمِيلَةٍ", "segs": [{"ar": "لَوْ لَمْ تَكُنْ لَدَيَّ ذَرَّةٌ مِنْ شَفَقَةٍ لَمَا أَتَيْتُكِ بِالطَّعَامِ رَغْمَ حِدَّةِ لِسَانِكِ", "uz": "agar mendi bir zarracha shafqat bo'lmaganda, til achchiqligingga qaramay senga ovqat olib kelmasdim"}, {"ar": "الَّذِي سَأَحْرِصُ عَلَى تَرْوِيضِهِ لِيُصْبِحَ لَائِقًا بِجَارِيَةٍ مُطِيعَةٍ وَجَمِيلَةٍ", "uz": "va uni itoatkor hamda go'zal cho'ri kanizakka mos bo'lguncha jilovlashga harakat qilaman"}], "full_uz": "Agar mendi bir zarracha shafqat bo'lmaganda, til achchiqligingga qaramay senga ovqat olib kelmasdim — va uni itoatkor hamda go'zal cho'ri kanizakka mos bo'lguncha jilovlashga harakat qilaman.", "note": null},
  {"num": 98, "time": "00:06:23,120 --> 00:06:26,000", "arabic": "أَنَا لَسْتُ جَارِيَةً أَيَّتُهَا الْمَرْأَةُ السَّمِجَةُ", "segs": null, "full_uz": "Men cho'ri emasman, ey qo'pol ayol.", "note": null},
  {"num": 99, "time": "00:06:26,000 --> 00:06:32,139", "arabic": "أَنَا فَتَاةٌ حُرَّةٌ ابْنَةُ تَاجِرٍ حُرٍّ شَرِيفٍ وَسَأَبْقَى حُرَّةً حَتَّى آخِرِ يَوْمٍ فِي عُمْرِي", "segs": [{"ar": "أَنَا فَتَاةٌ حُرَّةٌ ابْنَةُ تَاجِرٍ حُرٍّ شَرِيفٍ", "uz": "men erkin qizman, sharafli va erkin savdogarning qizi"}, {"ar": "وَسَأَبْقَى حُرَّةً حَتَّى آخِرِ يَوْمٍ فِي عُمْرِي", "uz": "va umrimning oxirgi kunigacha erkin bo'lib qolaman"}], "full_uz": "Men erkin qizman, sharafli va erkin savdogarning qizi, va umrimning oxirgi kunigacha erkin bo'lib qolaman.", "note": null},
  {"num": 100, "time": "00:06:32,139 --> 00:06:36,500", "arabic": "زَمَنُ الْحُرِّيَّةِ", "segs": null, "full_uz": "Erkinlik zamoni-a.", "note": null},
  {"num": 101, "time": "00:06:36,500 --> 00:06:44,500", "arabic": "وَاللَّهِ مِنَ الْآنَ فَصَاعِدًا أَنْتِ جَارِيَةٌ زُمُرُّدَةُ، عَلَيْكِ أَنْ تُقْنِعِي نَفْسَكِ بِذَلِكَ", "segs": null, "full_uz": "Vallohi, bundan buyon sen Zumurrad ismli cho'risan, buni o'zingga qabul qildirishing kerak.", "note": "«مِنَ الْآنَ فَصَاعِدًا» — «shu paytdan boshlab, bundan buyon» ma'nosidagi ibora."},
  {"num": 102, "time": "00:06:44,500 --> 00:07:02,500", "arabic": "هَلْ سَمِعْتَ عَنْ فَتَاتَيْنِ ضَائِعَتَيْنِ يَا أَخِي؟", "segs": null, "full_uz": "Ikki adashib qolgan qiz haqida eshitdingmi, birodar?", "note": null},
  {"num": 103, "time": "00:07:02,500 --> 00:07:06,500", "arabic": "يَا أَبَا فَوْزٍ، أَبَا فَوْزٍ، أَيْنَ أَنْتَ يَا رَجُلُ؟", "segs": null, "full_uz": "Abu Favz, Abu Favz, qayerdasan, odam bola?", "note": null},
  {"num": 104, "time": "00:07:06,500 --> 00:07:07,899", "arabic": "لَقَدْ تَعِبْتُ وَأَنَا أَبْحَثُ عَنْكَ", "segs": null, "full_uz": "Seni izlayverib charchadim.", "note": null},
  {"num": 105, "time": "00:07:07,899 --> 00:07:10,860", "arabic": "يَجِبُ أَنْ تَسِيرَ الْقَافِلَةُ، لَقَدْ تَأَخَّرْنَا كَثِيرًا", "segs": null, "full_uz": "Karvon yo'lga chiqishi kerak, biz juda kechikdik.", "note": null},
  {"num": 107, "time": "00:07:10,860 --> 00:07:15,079", "arabic": "يَا أَبَا رُسْتُمَ، أَلَمْ أَطْلُبْ إِلَيْكَ بِالْأَمْسِ الِانْتِظَارَ يَوْمًا آخَرَ؟", "segs": null, "full_uz": "Abu Rustam, kecha senga yana bir kun kutishni so'ramaganmidim?", "note": null},
  {"num": 110, "time": "00:07:15,079 --> 00:07:19,199", "arabic": "أُقْسِمُ أَنَّنِي حَاوَلْتُ، لَكِنَّ الْقَوْمَ يُصِرُّونَ عَلَى الذَّهَابِ", "segs": null, "full_uz": "Qasam ichamanki, harakat qildim, lekin odamlar ketishda qat'iy turishibdi.", "note": null},
  {"num": 112, "time": "00:07:19,199 --> 00:07:22,220", "arabic": "إِنْ شِئْتَ رَافِقْنَا وَإِلَّا فَابْقَ حَتَّى تَنْتَهِيَ مِنْ عَمَلِكَ", "segs": null, "full_uz": "Agar xohlasang, biz bilan yur, aks holda ishing tugaguncha shu yerda qol.", "note": null},
  {"num": 114, "time": "00:07:22,220 --> 00:07:24,980", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "Faqat Allohning yordami bilangina kuch-quvvat bor.", "note": "Bu — musulmonlarning mashhur zikr iborasi («hawqala»), qiyinchilik yoki g'azab paytida aytiladi."},
  {"num": 116, "time": "00:07:28,240 --> 00:07:33,680", "arabic": "اَلرَّحْمَةَ يَا مَوْلَايَ", "segs": null, "full_uz": "Rahm qiling, xo'jayinim.", "note": null},
  {"num": 118, "time": "00:07:35,920 --> 00:07:41,420", "arabic": "قُلْ مَنْ كَانَ مَعَكَ فِي هَذِهِ الْمُؤَامَرَةِ الْخَبِيثَةِ وَانْجُ بِنَفْسِكَ مِنْ مَوْتٍ مُحَقَّقٍ", "segs": [{"ar": "قُلْ مَنْ كَانَ مَعَكَ فِي هَذِهِ الْمُؤَامَرَةِ الْخَبِيثَةِ", "uz": "bu xabis fitnada sen bilan kim bo'lganini ayt"}, {"ar": "وَانْجُ بِنَفْسِكَ مِنْ مَوْتٍ مُحَقَّقٍ", "uz": "va o'zingni aniq o'limdan qutqar"}], "full_uz": "Bu xabis fitnada sen bilan kim bo'lganini ayt, va o'zingni aniq o'limdan qutqar.", "note": null},
  {"num": 119, "time": "00:07:41,420 --> 00:07:44,920", "arabic": "لَا أَعْرِفُ أَحَدًا", "segs": null, "full_uz": "Hech kimni tanimayman.", "note": null},
  {"num": 120, "time": "00:07:44,920 --> 00:07:47,420", "arabic": "أَنْتَ هَالِكٌ إِنْ لَمْ تَتَكَلَّمْ يَا ابْنَ الْأَيْهَمِ", "segs": null, "full_uz": "Agar gapirmasang, halok bo'lasan, Ibn al-Ayham.", "note": null},
  {"num": 121, "time": "00:07:47,420 --> 00:07:54,780", "arabic": "وَأُقْسِمُ إِنَّنِي لَنْ أَدَعَهُمْ يَكُفُّونَ عَنْ ضَرْبِكَ حَتَّى تُقِرَّ بِأَسْمَاءِ مَنْ مَعَكَ مِنَ الْخَوَنَةِ الْمَارِقِينَ", "segs": [{"ar": "وَأُقْسِمُ إِنَّنِي لَنْ أَدَعَهُمْ يَكُفُّونَ عَنْ ضَرْبِكَ", "uz": "qasam ichamanki, ularni seni urishdan to'xtatib qo'ymayman"}, {"ar": "حَتَّى تُقِرَّ بِأَسْمَاءِ مَنْ مَعَكَ مِنَ الْخَوَنَةِ الْمَارِقِينَ", "uz": "toki sen bilan bo'lgan xoin-mo'tadillarning ismlarini tan olmaguningcha"}], "full_uz": "Qasam ichamanki, ularni seni urishdan to'xtatib qo'ymayman, toki sen bilan bo'lgan xoinlarning ismlarini tan olmaguningcha.", "note": null},
  {"num": 123, "time": "00:07:54,780 --> 00:07:59,780", "arabic": "قُلْتُ لَكُمْ لَا أَعْرِفُ أَحَدًا", "segs": null, "full_uz": "Sizlarga aytdim-ku, hech kimni tanimayman.", "note": null},
  {"num": 124, "time": "00:07:59,780 --> 00:08:02,340", "arabic": "سُكُوتُكَ يُعَجِّلُ أَجَلَكَ يَا ابْنَ الْأَيْهَمِ", "segs": null, "full_uz": "Jimliging ajalingni tezlashtiryapti, Ibn al-Ayham.", "note": null},
  {"num": 125, "time": "00:08:02,339 --> 00:08:03,179", "arabic": "خُذُوهُ", "segs": null, "full_uz": "Uni olib keting.", "note": null},
  {"num": 126, "time": "00:08:03,179 --> 00:08:09,479", "arabic": "خُذُوهُ وَلَا تَتْرُكُوهُ قَبْلَ أَنْ يَعْتَرِفَ بِأَسْمَاءِ كُلِّ مَنْ مَعَهُ مِنَ الْخَائِنِينَ", "segs": null, "full_uz": "Uni olib keting va u bilan birga bo'lgan barcha xoinlarning ismlarini tan olmaguncha qo'yib yubormang.", "note": null},
  {"num": 130, "time": "00:08:25,479 --> 00:08:27,539", "arabic": "لَا تَقْلَقْ يَا مَوْلَايَ", "segs": null, "full_uz": "Xavotir olmang, xo'jayinim.", "note": null},
  {"num": 131, "time": "00:08:27,539 --> 00:08:31,620", "arabic": "سَيَعْتَرِفُ هَذَا الْخَائِنُ عَاجِلًا أَمْ آجِلًا", "segs": null, "full_uz": "Bu xoin erta-kech tan oladi.", "note": null},
  {"num": 132, "time": "00:08:31,620 --> 00:08:33,440", "arabic": "لَا لَا لَا لَا يَا يَحْيَى", "segs": null, "full_uz": "Yo'q, yo'q, yo'q, yo'q, Yahyo.", "note": null},
  {"num": 133, "time": "00:08:33,440 --> 00:08:37,039", "arabic": "مِنَ الْأَفْضَلِ أَنْ يَعْتَرِفَ عَاجِلًا", "segs": null, "full_uz": "Tezroq tan olgani ma'qul.", "note": null},
  {"num": 134, "time": "00:08:37,039 --> 00:08:44,560", "arabic": "مَا أَدْرَاكَ؟ قَدْ يَكُونُ وَرَاءَ هَذِهِ الْمُؤَامَرَةِ دُهَاةٌ كُثُرٌ", "segs": null, "full_uz": "Qayerdan bilasan? Balki bu fitna orqasida ko'plab ayyor odamlar bordir.", "note": "«مَا أَدْرَاكَ؟» — «sen qayerdan bilasan?, sen bilmaysan» ma'nosidagi shubha bildiruvchi ibora."},
  {"num": 136, "time": "00:08:44,560 --> 00:08:48,039", "arabic": "وَقَدْ يَكُونُ بَعْضُهُمْ بَيْنَ ظَهْرَانَيْنَا", "segs": null, "full_uz": "Va ulardan ba'zilari bizning orangizda bo'lishi mumkin.", "note": null},
  {"num": 137, "time": "00:08:48,039 --> 00:08:59,740", "arabic": "ثَلَاثَةُ أَيَّامٍ يَا يَحْيَى، أَمَامَكُمْ ثَلَاثَةُ أَيَّامٍ حَتَّى تُحْضِرُوا الْمُتَوَرِّطِينَ مَعَهُ", "segs": [{"ar": "ثَلَاثَةُ أَيَّامٍ يَا يَحْيَى", "uz": "uch kun, Yahyo"}, {"ar": "أَمَامَكُمْ ثَلَاثَةُ أَيَّامٍ حَتَّى تُحْضِرُوا الْمُتَوَرِّطِينَ مَعَهُ", "uz": "uning sherigi bo'lganlarni olib kelishga uch kun vaqtingiz bor"}], "full_uz": "Uch kun, Yahyo. Uning sherigi bo'lganlarni olib kelishga uch kun vaqtingiz bor.", "note": null},
  {"num": 139, "time": "00:08:59,740 --> 00:09:04,399", "arabic": "وَإِلَّا فَسَأَحْسِمُ الْأَمْرَ، إِنِّي سَأَضَعُ الْجَمِيعَ مَعَهُ", "segs": null, "full_uz": "Aks holda, o'zim hal qilaman — hammani u bilan bir qatorga qo'yaman.", "note": null},
  {"num": 141, "time": "00:09:04,399 --> 00:09:06,000", "arabic": "أَمْرُ مَوْلَايَ", "segs": null, "full_uz": "Xo'jayinimning amri.", "note": null},
  {"num": 142, "time": "00:09:31,000 --> 00:09:36,000", "arabic": "إِلَى مَتَى؟", "segs": null, "full_uz": "Qachongacha?", "note": null},
  {"num": 143, "time": "00:09:36,000 --> 00:09:41,000", "arabic": "إِلَى مَتَى سَتَصْمُدُ يَدُ الْأَيَّامِ؟", "segs": null, "full_uz": "Kunlar qo'li qachongacha bardosh berar ekan?", "note": "«يَدُ الْأَيَّامِ» — «kunlar qo'li» — vaqt/taqdirni shaxslashtiruvchi badiiy ibora."},
  {"num": 145, "time": "00:10:31,000 --> 00:10:43,279", "arabic": "اِبْنُ أَخِي الْآنَ أَمَانَةٌ فِي عُنُقِكَ يَا زَيْدُ", "segs": null, "full_uz": "Jiyanim endi sening bo'yningdagi omonat, Zayd.", "note": null},
  {"num": 146, "time": "00:10:43,279 --> 00:10:46,519", "arabic": "بِإِذْنِ اللَّهِ سَأَكُونُ لَهُ سَنَدًا وَعَوْنًا", "segs": null, "full_uz": "Alloh xohlasa, unga tayanch va yordamchi bo'laman.", "note": null},
  {"num": 147, "time": "00:10:46,519 --> 00:10:51,379", "arabic": "بَارَكَ اللَّهُ فِيكَ، أَتَمَنَّى عَلَيْكَ أَنْ تَكُونَ لَهُ عَوْنًا فِي التَّوْفِيقِ بَيْنَ عِلْمِهِ وَعَمَلِهِ", "segs": null, "full_uz": "Alloh senga baraka bersin, undan ilmi bilan mehnatini muvofiqlashtirishda unga yordamchi bo'lishingni umid qilaman.", "note": null},
  {"num": 148, "time": "00:10:51,379 --> 00:10:53,840", "arabic": "لَا عَلَيْكَ يَا أَبَا حَنْبَلٍ لَا عَلَيْكَ", "segs": null, "full_uz": "Xavotir olma, Abu Hanbal, xavotir olma.", "note": null},
  {"num": 149, "time": "00:10:53,840 --> 00:10:55,899", "arabic": "بَارَكَ اللَّهُ فِيكَ، اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Alloh senga baraka bersin, sizga salom.", "note": null},
  {"num": 150, "time": "00:10:55,899 --> 00:10:58,519", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Sizga ham salom, Allohning rahmati va barakoti bo'lsin.", "note": null},
  {"num": 152, "time": "00:11:31,000 --> 00:11:41,580", "arabic": "أَحْمَدُ، أَلَنْ تَبْدَأَ الْعَمَلَ؟", "segs": null, "full_uz": "Ahmad, ishni boshlamaysanmi?", "note": null},
  {"num": 153, "time": "00:11:41,580 --> 00:11:43,200", "arabic": "بِكُلِّ تَأْكِيدٍ بِعَوْنِ اللَّهِ", "segs": null, "full_uz": "Albatta, Allohning yordami bilan.", "note": null},
  {"num": 155, "time": "00:12:31,000 --> 00:12:35,480", "arabic": "أَنَا عَامِرٌ الْإِسْكَافِيُّ صَاحِبُ الدُّكَّانِ مُرَقِّعِ النِّعَالِ", "segs": null, "full_uz": "Men etikdo'z Omirman, na'llarni yamovchi do'kon egasi.", "note": null},
  {"num": 156, "time": "00:12:35,480 --> 00:12:37,139", "arabic": "مُبَارَكٌ يَا عَامِرُ", "segs": null, "full_uz": "Muborak bo'lsin, Omir.", "note": null},
  {"num": 157, "time": "00:12:37,139 --> 00:12:39,220", "arabic": "بَارَكَ اللَّهُ فِيكَ، بَارَكَ اللَّهُ فِيكُمْ", "segs": null, "full_uz": "Alloh senga baraka bersin, Alloh sizlarga baraka bersin.", "note": null},
  {"num": 158, "time": "00:12:39,220 --> 00:12:41,419", "arabic": "جَعَلَهَا اللَّهُ بَابَ رِزْقٍ وَنَعِيمٍ", "segs": null, "full_uz": "Alloh uni rizq va ne'mat eshigi qilsin.", "note": null},
  {"num": 159, "time": "00:12:41,419 --> 00:12:43,720", "arabic": "إِنْ شَاءَ اللَّهُ، تَوَكَّلْنَا عَلَى اللَّهِ", "segs": null, "full_uz": "Alloh xohlasa, Allohga tavakkal qildik.", "note": null},
  {"num": 160, "time": "00:12:43,720 --> 00:12:49,940", "arabic": "وَنِعْمَ الِاتِّكَالُ، أَوَّلُ نِعَالٍ تَصْنَعُهُ مِنْ جِلْدِ الْبَعِيرِ تُهْدِيهِ لِابْنِ الْوَزِيرِ", "segs": [{"ar": "وَنِعْمَ الِاتِّكَالُ", "uz": "va bu qanday go'zal tavakkal"}, {"ar": "أَوَّلُ نِعَالٍ تَصْنَعُهُ مِنْ جِلْدِ الْبَعِيرِ تُهْدِيهِ لِابْنِ الْوَزِيرِ", "uz": "tuya terisidan qilgan birinchi na'lingni vazirning o'g'liga sovg'a qilasan"}], "full_uz": "Va bu qanday go'zal tavakkal — tuya terisidan qilgan birinchi na'lingni vazirning o'g'liga sovg'a qilasan.", "note": null},
  {"num": 161, "time": "00:12:49,940 --> 00:13:01,000", "arabic": "وَيْحَكَ يَا أَبَا سَرْعَانَ، اُغْضُضْ صَوْتَكَ، فَعُيُونُ أَمِيرِ الْمُؤْمِنِينَ خَلْفَ كُلِّ زَاوِيَةٍ فِي السُّوقِ", "segs": [{"ar": "وَيْحَكَ يَا أَبَا سَرْعَانَ، اُغْضُضْ صَوْتَكَ", "uz": "voy senga, Abu Sar'an, ovozingni pasaytir"}, {"ar": "فَعُيُونُ أَمِيرِ الْمُؤْمِنِينَ خَلْفَ كُلِّ زَاوِيَةٍ فِي السُّوقِ", "uz": "chunki mo'minlar amirining ko'zlari bozorning har burchagida"}], "full_uz": "Voy senga, Abu Sar'an, ovozingni pasaytir, chunki mo'minlar amirining ko'zlari bozorning har burchagida.", "note": "«عُيُونُ أَمِيرِ الْمُؤْمِنِينَ» — «amirning ko'zlari», ya'ni hukmdorning ayg'oqchi/josuslari ma'nosidagi majoziy ibora."},
  {"num": 162, "time": "00:13:07,919 --> 00:13:10,799", "arabic": "لِمَاذَا كُلُّ هَذَا الْعُبُوسِ الَّذِي لَا يُفَارِقُ وَجْهَكَ نَكِدٌ؟", "segs": null, "full_uz": "Nega yuzingdan hech ajralmaydigan bu qovog'ing solingan, kayfiyating buzuq?", "note": null},
  {"num": 163, "time": "00:13:10,799 --> 00:13:13,200", "arabic": "نَكِدٌ؟ لَا شَيْءَ، لَا شَيْءَ", "segs": null, "full_uz": "Kayfiyatim buzuqmi? Hech narsa, hech narsa.", "note": null},
  {"num": 164, "time": "00:13:13,200 --> 00:13:16,399", "arabic": "لَا شَيْءَ؟ حَمْدُ اللَّهِ", "segs": null, "full_uz": "Hech narsa emasmi? Alhamdulillоh.", "note": null},
  {"num": 165, "time": "00:13:16,399 --> 00:13:18,159", "arabic": "أَعْرِفُكَ كَمَا أَعْرِفُ رَاحَةَ يَدِي", "segs": null, "full_uz": "Seni xuddi o'z kaftimdek bilaman.", "note": "«يَعْرِفُهُ كَرَاحَةِ يَدِهِ» — «kaftini bilgandek bilmoq», ya'ni kimsani juda yaxshi, mukammal bilish ma'nosidagi ibora."},
  {"num": 166, "time": "00:13:18,159 --> 00:13:23,500", "arabic": "قُلْ مَا عِنْدَكَ", "segs": null, "full_uz": "Ko'nglingdagini ayt.", "note": null},
  {"num": 167, "time": "00:13:23,500 --> 00:13:29,080", "arabic": "بِصَرَاحَةٍ أَخْشَى أَنْ يُكْشَفَ أَمْرُنَا فَيُزَجَّ بِنَا فِي سِجْنِ بَغْدَادَ، بَدَلَ أَنْ نَكْسِبَ الْمَالَ مِنْ بَيْعِ هَذِهِ الْفَتَاةِ", "segs": [{"ar": "بِصَرَاحَةٍ أَخْشَى أَنْ يُكْشَفَ أَمْرُنَا فَيُزَجَّ بِنَا فِي سِجْنِ بَغْدَادَ", "uz": "rostini aytsam, sirimiz oshkor bo'lib, Bag'dod zindoniga tashlanishimizdan qo'rqaman"}, {"ar": "بَدَلَ أَنْ نَكْسِبَ الْمَالَ مِنْ بَيْعِ هَذِهِ الْفَتَاةِ", "uz": "bu qizni sotishdan pul topish o'rniga"}], "full_uz": "Rostini aytsam, sirimiz oshkor bo'lib, Bag'dod zindoniga tashlanishimizdan qo'rqaman — bu qizni sotishdan pul topish o'rniga.", "note": "«يُزَجُّ بِـ» — «tashlab yubormoq, otib yubormoq» (zindon yoki qiyin holatga) ma'nosidagi majhul nisbatdagi fe'l."},
  {"num": 169, "time": "00:13:32,779 --> 00:13:37,180", "arabic": "يَا رَجُلُ، يَا ذَكِيُّ", "segs": null, "full_uz": "Hoy odam, ey aqlli.", "note": null},
  {"num": 170, "time": "00:13:37,180 --> 00:13:18,680", "arabic": "أَلَيْسَ لَدَيْنَا صَكٌّ يُثْبِتُ مِلْكِيَّتَنَا لَهَا عَلَى أَنَّهَا جَارِيَةٌ؟ أَمْ أَنَّكَ نَسِيتَ؟", "segs": null, "full_uz": "Uning bizga qarashli cho'ri ekanligini isbotlovchi hujjatimiz yo'qmi? Yoki unutdingmi?", "note": null},
  {"num": 172, "time": "00:13:18,680 --> 00:13:23,060", "arabic": "لَمْ أَنْسَ، وَلَكِنَّ الصَّكَّ الَّذِي وَجَدْنَاهُ فِي السُّوقِ هُوَ لِفَتَاةٍ ثَانِيَةٍ، وَاسْمُهَا غَيْرُ اسْمِ هَذِهِ الْفَتَاةِ", "segs": [{"ar": "لَمْ أَنْسَ، وَلَكِنَّ الصَّكَّ الَّذِي وَجَدْنَاهُ فِي السُّوقِ هُوَ لِفَتَاةٍ ثَانِيَةٍ", "uz": "unutmadim, lekin bozorda topgan hujjatimiz boshqa qizga tegishli"}, {"ar": "وَاسْمُهَا غَيْرُ اسْمِ هَذِهِ الْفَتَاةِ", "uz": "va uning ismi bu qizning ismidan farq qiladi"}], "full_uz": "Unutmadim, lekin bozorda topgan hujjatimiz boshqa qizga tegishli, va uning ismi bu qizning ismidan farq qiladi.", "note": null},
  {"num": 175, "time": "00:13:44,720 --> 00:13:49,080", "arabic": "ثُمَّ أَخْشَى أَنَّهَا سَتُخْبِرُ مَنْ يُرِيدُ شِرَاءَهَا غَدًا الْحَقِيقَةَ كَامِلَةً", "segs": null, "full_uz": "Bundan tashqari, u ertaga uni sotib olmoqchi bo'lgan kishiga to'liq haqiqatni aytib qo'yishidan qo'rqaman.", "note": null},
  {"num": 176, "time": "00:13:49,080 --> 00:13:53,180", "arabic": "وَمَنِ الَّذِي سَيُصَدِّقُ جَارِيَةً وَيُكَذِّبُ مَالِكًا؟", "segs": null, "full_uz": "Kim cho'riga ishonib, egasini yolg'onchiga chiqaradi?", "note": null},
  {"num": 177, "time": "00:13:53,179 --> 00:13:57,659", "arabic": "اَلصَّكُّ الَّذِي مَعَنَا هُوَ حَقِيقَتُهَا الَّتِي لَنْ يَسْتَطِيعَ أَحَدٌ إِنْكَارَهَا", "segs": null, "full_uz": "Bizdagi hujjat — uning hech kim inkor eta olmaydigan haqiqatidir.", "note": null},
  {"num": 178, "time": "00:13:57,659 --> 00:14:00,759", "arabic": "لَا تَخْشَ شَيْئًا وَدَعْ عَنْكَ الْخَوْفَ", "segs": null, "full_uz": "Hech narsadan qo'rqma va qo'rquvni tashlab qo'y.", "note": null},
  {"num": 179, "time": "00:14:23,179 --> 00:14:45,399", "arabic": "عُذْرًا يَا سَيِّدِي، لَقَدْ تَأَخَّرْتُ عَنْ حَلْقَةِ شَيْخِي", "segs": null, "full_uz": "Uzr, hazratim, shayximning darsiga kechikdim.", "note": null},
  {"num": 180, "time": "00:14:45,399 --> 00:14:52,539", "arabic": "أَعْرِفُ، وَأَعْرِفُ أَنَّنِي قَدْ قَطَعْتُ عَهْدًا مَعَ عَمِّكَ أَنْ أَضَعَ ذَلِكَ نُصْبَ عَيْنِي، وَلَكِنْ", "segs": [{"ar": "أَعْرِفُ، وَأَعْرِفُ أَنَّنِي قَدْ قَطَعْتُ عَهْدًا مَعَ عَمِّكَ", "uz": "bilaman, va amaking bilan ahd qilganimni ham bilaman"}, {"ar": "أَنْ أَضَعَ ذَلِكَ نُصْبَ عَيْنِي، وَلَكِنْ", "uz": "buni ko'z oldimda tutishga, ammo"}], "full_uz": "Bilaman, va amaking bilan buni ko'z oldimda tutishga ahd qilganimni ham bilaman, ammo...", "note": "«نُصْبَ عَيْنِهِ» — «ko'z oldida, e'tiborda tutgan holda» ma'nosidagi ibora."},
  {"num": 181, "time": "00:14:52,539 --> 00:14:55,079", "arabic": "اَلْمُؤْمِنُونَ عِنْدَ شُرُوطِهِمْ يَا سَيِّدِي", "segs": null, "full_uz": "Mo'minlar o'z shartlariga sodiqdirlar, hazratim.", "note": "Bu — «Mo'minlar o'z shartlarida turadilar» mazmunidagi mashhur hadisga asoslangan huquqiy-axloqiy qoida."},
  {"num": 182, "time": "00:14:55,079 --> 00:14:57,379", "arabic": "وَأَنَا أُنَفِّذُ مَا وَعَدْتُ يَا أَحْمَدُ", "segs": null, "full_uz": "Men ham va'da qilganimni bajaraman, Ahmad.", "note": null},
  {"num": 183, "time": "00:14:57,379 --> 00:15:01,419", "arabic": "وَلَكِنْ مَا إِنْ تَنْتَهِيَ حَلْقَةُ الدَّرْسِ حَتَّى تَعُودَ إِلَى الْعَمَلِ، فَلَدَيْنَا عَمَلٌ كَثِيرٌ الْيَوْمَ", "segs": [{"ar": "وَلَكِنْ مَا إِنْ تَنْتَهِيَ حَلْقَةُ الدَّرْسِ حَتَّى تَعُودَ إِلَى الْعَمَلِ", "uz": "lekin dars halqasi tugashi bilan ishga qaytishing kerak"}, {"ar": "فَلَدَيْنَا عَمَلٌ كَثِيرٌ الْيَوْمَ", "uz": "chunki bugun bizda ish ko'p"}], "full_uz": "Lekin dars halqasi tugashi bilan ishga qaytishing kerak, chunki bugun bizda ish ko'p.", "note": null},
  {"num": 185, "time": "00:15:01,419 --> 00:15:05,579", "arabic": "وَأَنَا أَفِي بِوَعْدِي إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Men ham va'damga vafo qilaman, Alloh xohlasa.", "note": null},
  {"num": 186, "time": "00:15:05,579 --> 00:15:07,179", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Sizga salom.", "note": null},
  {"num": 187, "time": "00:15:07,179 --> 00:15:09,279", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Sizga ham salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 188, "time": "00:15:16,480 --> 00:15:18,799", "arabic": "لَا تَيْأَسِي مِنْ رَحْمَةِ اللَّهِ يَا أُخْتِي", "segs": null, "full_uz": "Allohning rahmatidan umidsizlanma, singlim.", "note": "Bu ibora Qur'ondagi «Allohning rahmatidan umidsizlanmanglar» mazmunidagi oyatga ishora qiladi."},
  {"num": 189, "time": "00:15:18,799 --> 00:15:21,579", "arabic": "سَنَبْحَثُ فِي بَغْدَادَ كُلِّهَا", "segs": null, "full_uz": "Butun Bag'dodni izlaymiz.", "note": null},
  {"num": 190, "time": "00:15:21,580 --> 00:15:24,160", "arabic": "بَغْدَادُ كَبِيرَةٌ جِدًّا يَا شَهْنَازُ", "segs": null, "full_uz": "Bag'dod juda katta, Shahnoz.", "note": null},
  {"num": 191, "time": "00:15:24,160 --> 00:15:32,000", "arabic": "وَلَكِنْ، لَقَدْ أَخْبَرَنَا صَاحِبُ النُّزُلِ أَنَّ قَافِلَةَ خُرَاسَانَ قَدْ غَادَرَتْ بَغْدَادَ", "segs": [{"ar": "وَلَكِنْ، لَقَدْ أَخْبَرَنَا صَاحِبُ النُّزُلِ", "uz": "lekin, mehmonxona egasi bizga aytdi"}, {"ar": "أَنَّ قَافِلَةَ خُرَاسَانَ قَدْ غَادَرَتْ بَغْدَادَ", "uz": "Xuroson karvoni Bag'doddan chiqib ketganini"}], "full_uz": "Lekin mehmonxona egasi bizga Xuroson karvoni Bag'doddan chiqib ketganini aytdi.", "note": null},
  {"num": 195, "time": "00:15:32,000 --> 00:15:34,139", "arabic": "رُبَّمَا يَكُونُ أَبُوكِ قَدْ تَخَلَّفَ عَنْهُ", "segs": null, "full_uz": "Balki otang undan orqada qolgandir.", "note": null},
  {"num": 196, "time": "00:15:34,139 --> 00:15:36,940", "arabic": "لِمَاذَا تَسْتَعْجِلِينَ السَّيِّئَةَ؟", "segs": null, "full_uz": "Nega yomon narsani shoshib o'ylayapsan?", "note": null},
  {"num": 197, "time": "00:15:36,940 --> 00:15:39,600", "arabic": "اِطْمَئِنِّي يَا شَهْنَازُ، سَأَخُذُكِ إِلَى الدَّارِ", "segs": null, "full_uz": "Xotirjam bo'l, Shahnoz, seni uyga olib boraman.", "note": null},
  {"num": 199, "time": "00:15:39,600 --> 00:15:42,540", "arabic": "وَأَعِدُكِ بِأَنَّنِي لَنْ أَكُفَّ عَنِ الْبَحْثِ عَنْهُمَا", "segs": null, "full_uz": "Va senga va'da beramanki, ikkovlarini izlashdan to'xtamayman.", "note": null},
  {"num": 200, "time": "00:15:42,540 --> 00:15:43,500", "arabic": "لَا", "segs": null, "full_uz": "Yo'q.", "note": null},
  {"num": 201, "time": "00:15:43,500 --> 00:15:47,840", "arabic": "لَنْ تَقَرَّ لِي عَيْنٌ حَتَّى أَعْثُرَ عَلَيْهِمَا", "segs": null, "full_uz": "Ularni topmagunimcha ko'zim tinchimaydi.", "note": "«لَنْ تَقَرَّ لِي عَيْنٌ» — «ko'zim tinchimaydi», ya'ni orzu-maqsadga yetmaguncha xotirjamlik topmaslik ma'nosidagi ibora."},
  {"num": 203, "time": "00:15:47,879 --> 00:15:50,540", "arabic": "أَجَلْ أَجَلْ، خَالِدُ", "segs": null, "full_uz": "Ha, ha. Xolid!", "note": null},
  {"num": 205, "time": "00:15:50,539 --> 00:15:56,559", "arabic": "لِمَاذَا لَمْ تَفْتَحْ دُكَّانَكَ حَتَّى الْآنَ؟ لَقَدْ سَأَلَ عَنْكَ الْبَعْضُ", "segs": null, "full_uz": "Nega hozirgacha do'koningni ochmading? Ba'zilar seni so'rab qolishdi.", "note": null},
  {"num": 206, "time": "00:15:56,559 --> 00:15:58,319", "arabic": "كُنْتُ فِي شَأْنٍ مَا", "segs": null, "full_uz": "Bir ishim bilan mashg'ul edim.", "note": null},
  {"num": 207, "time": "00:15:58,319 --> 00:16:02,219", "arabic": "مَا بِهَا وَلِمَاذَا تَبْكِي؟", "segs": null, "full_uz": "Unga nima bo'ldi, nega yig'lyapti?", "note": null},
  {"num": 208, "time": "00:16:02,219 --> 00:16:03,679", "arabic": "مِسْكِينَةٌ، لَقَدْ أَضَاعَتْ أَهْلَهَا", "segs": null, "full_uz": "Bechora, u oila-a'zolaridan adashib qolgan.", "note": null},
  {"num": 209, "time": "00:16:03,679 --> 00:16:06,459", "arabic": "أَضَاعَتْ أَهْلَهَا؟ كَيْفَ؟", "segs": null, "full_uz": "Oila-a'zolaridan adashdimi? Qanday qilib?", "note": null},
  {"num": 210, "time": "00:16:06,459 --> 00:16:07,519", "arabic": "سَأُخْبِرُكَ فِيمَا بَعْدُ", "segs": null, "full_uz": "Keyinroq aytib beraman.", "note": null},
  {"num": 211, "time": "00:16:07,519 --> 00:16:09,299", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Sizga salom.", "note": null},
  {"num": 212, "time": "00:16:09,299 --> 00:16:10,279", "arabic": "وَعَلَيْكُمُ السَّلَامُ", "segs": null, "full_uz": "Sizga ham salom.", "note": null},
  {"num": 213, "time": "00:16:10,279 --> 00:16:11,919", "arabic": "هَيَّا يَا شَهْنَازُ هَيَّا", "segs": null, "full_uz": "Yur, Shahnoz, yur.", "note": null},
  {"num": 215, "time": "00:16:44,539 --> 00:16:44,679", "arabic": "مُرَّ كَاتِبَكَ فِي الْمَدِينَةِ الْمُنَوَّرَةِ نُرْسِلْهُ كِتَابًا مِثْلَ هَذَا الْكِتَابِ", "segs": null, "full_uz": "Madinai Munavvaradagi kotibingga ayt, biz unga ham shunga o'xshash bir maktub yuboramiz.", "note": null},
  {"num": 217, "time": "00:16:50,219 --> 00:16:52,679", "arabic": "يَحْيَى", "segs": null, "full_uz": "Yahyo!", "note": null},
  {"num": 218, "time": "00:16:52,679 --> 00:16:56,740", "arabic": "أَمْرُ مَوْلَايَ", "segs": null, "full_uz": "Xo'jayinimning amri.", "note": null},
  {"num": 219, "time": "00:16:56,740 --> 00:17:03,919", "arabic": "إِلَى أَيْنَ وَصَلْتُمْ مَعَ ابْنِ الْأَيْهَمِ؟", "segs": null, "full_uz": "Ibn al-Ayham bilan ishlar qayerga yetdi?", "note": null},
  {"num": 220, "time": "00:17:03,919 --> 00:17:08,000", "arabic": "كَأَنِّي بِهِ يَا مَوْلَايَ، قَدْ بَدَأَ يَتَخَلَّى عَنْ غُرُورِهِ وَتَلِينُ قَنَاتُهُ", "segs": [{"ar": "كَأَنِّي بِهِ يَا مَوْلَايَ", "uz": "menimcha, xo'jayinim"}, {"ar": "قَدْ بَدَأَ يَتَخَلَّى عَنْ غُرُورِهِ وَتَلِينُ قَنَاتُهُ", "uz": "u o'z kibri va'dan voz kecha boshladi va qat'iyati yumshamoqda"}], "full_uz": "Menimcha, xo'jayinim, u o'z kibridan voz kecha boshladi va qat'iyati yumshamoqda.", "note": "«تَلِينُ قَنَاتُهُ» — «uning nayzasi yumshaydi», ya'ni qat'iyati, jangovarligi so'nib, itoatkor bo'lib qolishi ma'nosidagi majoziy ibora."},
  {"num": 223, "time": "00:17:08,000 --> 00:17:10,960", "arabic": "كَأَنَّكَ", "segs": null, "full_uz": "Go'yoki sen...", "note": null},
  {"num": 224, "time": "00:17:10,960 --> 00:17:12,819", "arabic": "فَلْيَطْمَئِنَّ قَلْبُ مَوْلَايَ", "segs": null, "full_uz": "Xo'jayinimning qalbi xotirjam bo'lsin.", "note": null},
  {"num": 225, "time": "00:17:12,819 --> 00:17:19,039", "arabic": "غَدًا أَوْ بَعْدَ غَدٍ سَتَسْمَعُ مَا تَنْتَظِرُهُ", "segs": null, "full_uz": "Ertaga yoki indinga kutayotgan narsangni eshitasan.", "note": null},
  {"num": 227, "time": "00:17:19,039 --> 00:17:24,039", "arabic": "لَنْ يَطْمَئِنَّ قَلْبِي وَلَنْ يَقَرَّ لِي قَرَارٌ حَتَّى أُمْسِكَ بِنَاصِيَةِ هَؤُلَاءِ الْمَارِقِينَ", "segs": [{"ar": "لَنْ يَطْمَئِنَّ قَلْبِي وَلَنْ يَقَرَّ لِي قَرَارٌ", "uz": "qalbim tinchimaydi va xotirjamlik topmayman"}, {"ar": "حَتَّى أُمْسِكَ بِنَاصِيَةِ هَؤُلَاءِ الْمَارِقِينَ", "uz": "toki bu mo'tadillarni tor-mor qilmaguncha"}], "full_uz": "Qalbim tinchimaydi va xotirjamlik topmayman, toki bu isyonchilarni to'liq qo'lga olmaguncha.", "note": "«الْإِمْسَاكُ بِالنَّاصِيَةِ» — «peshonadan tutmoq», ya'ni birovni to'liq nazorat ostiga olish, mag'lub etish ma'nosidagi ibora."},
  {"num": 229, "time": "00:17:24,039 --> 00:17:26,940", "arabic": "وَأَجْعَلَهُمْ آيَةً لِمَنْ شَقَّ عَصَا الطَّاعَةِ", "segs": null, "full_uz": "Va ularni itoatdan bosh tortganlarga ibrat qilaman.", "note": "«شَقَّ عَصَا الطَّاعَةِ» — «itoat tayog'ini sindirmoq», ya'ni isyon ko'tarish, bo'ysunishdan bosh tortish ma'nosidagi ibora."},
  {"num": 230, "time": "00:17:26,940 --> 00:17:29,599", "arabic": "لَكَ مَا تُرِيدُ يَا مَوْلَايَ", "segs": null, "full_uz": "Xohlaganingiz bo'ladi, xo'jayinim.", "note": null},
  {"num": 231, "time": "00:17:45,000 --> 00:17:56,599", "arabic": "سَيَكُونُ لِي مَا أُرِيدُ، سَيَكُونُ لِي مَا أُرِيدُ وَإِلَّا", "segs": null, "full_uz": "Men xohlaganimga erishaman, xohlaganimga erishaman, aks holda...", "note": null},
  {"num": 233, "time": "00:17:56,599 --> 00:18:04,680", "arabic": "فِي حَلْقَةِ شَيْخِي لَوْمٌ عَلَى التَّأَخُّرِ، وَفِي دَارِ الْحِكْمَةِ لَوْمٌ عَلَى التَّأَخُّرِ", "segs": null, "full_uz": "Shayximning halqasida kechikish uchun ta'na, Ilm Uyida ham kechikish uchun ta'na.", "note": null},
  {"num": 235, "time": "00:18:04,680 --> 00:18:10,859", "arabic": "مَاذَا يَفْعَلُ بِنَفْسِهِ أَحْمَدُ بْنُ حَنْبَلٍ حَتَّى يُوَفِّقَ بَيْنَ الْعِلْمِ وَالْعَمَلِ؟", "segs": null, "full_uz": "Ahmad ibn Hanbal ilm bilan mehnatni muvofiqlashtirish uchun o'zi bilan nima qilsin?", "note": null},
  {"num": 237, "time": "00:18:10,859 --> 00:18:17,000", "arabic": "يَقُولُ لَكَ الْوَالِي يُرِيدُ أَخْبَارَ السُّوقِ، فَلَا تُفَوِّتْ صَغِيرَةً وَلَا كَبِيرَةً", "segs": [{"ar": "يَقُولُ لَكَ الْوَالِي يُرِيدُ أَخْبَارَ السُّوقِ", "uz": "voliy senga bozor haqidagi xabarlarni xohlaydi, deyapti"}, {"ar": "فَلَا تُفَوِّتْ صَغِيرَةً وَلَا كَبِيرَةً", "uz": "shu sabab kichik-yu katta hech narsani o'tkazib yuborma"}], "full_uz": "Voliy senga bozor haqidagi xabarlarni xohlaydi, deyapti — shu sabab kichik-yu katta hech narsani o'tkazib yuborma.", "note": null},
  {"num": 239, "time": "00:18:17,000 --> 00:18:24,719", "arabic": "وَرَكِّزْ جُلَّ اهْتِمَامِكَ عَلَى مَا يَقُولُهُ الْعُلَمَاءُ", "segs": null, "full_uz": "Va e'tiboringning ko'pini olimlarning gapiga qarat.", "note": null},
  {"num": 240, "time": "00:18:24,719 --> 00:18:31,479", "arabic": "صَدَقَ الْوَالِي فِي تَخَوُّفِهِ مِنْ أُولَئِكَ الْعُلَمَاءِ الَّذِينَ حَادُوا عَنْ طَرِيقِ الصَّوَابِ", "segs": null, "full_uz": "Voliy to'g'ri yo'ldan chetga chiqqan o'sha olimlardan xavotirlanishida haq.", "note": null},
  {"num": 241, "time": "00:18:31,479 --> 00:18:32,639", "arabic": "فِعْلًا", "segs": null, "full_uz": "Rostdan ham.", "note": null},
  {"num": 242, "time": "00:18:32,639 --> 00:18:41,459", "arabic": "فَهُمُ الْأَقْدَرُ عَلَى تَجْنِيدِ الشَّبَابِ لِلنَّيْلِ مِنَ الْخَلِيفَةِ وَالْبِلَادِ، وَالْأَقْدَرُ أَيْضًا عَلَى زَرْعِ الْفِتْنَةِ بَيْنَ النَّاسِ بِطَرِيقَةٍ أَوْ بِأُخْرَى", "segs": [{"ar": "فَهُمُ الْأَقْدَرُ عَلَى تَجْنِيدِ الشَّبَابِ لِلنَّيْلِ مِنَ الْخَلِيفَةِ وَالْبِلَادِ", "uz": "chunki ular xalifa va mamlakatga zarar yetkazish uchun yoshlarni safarbar qilishga eng qodirlaridir"}, {"ar": "وَالْأَقْدَرُ أَيْضًا عَلَى زَرْعِ الْفِتْنَةِ بَيْنَ النَّاسِ بِطَرِيقَةٍ أَوْ بِأُخْرَى", "uz": "va u yoki bu yo'l bilan odamlar orasiga nifoq solishga ham eng qodirlaridir"}], "full_uz": "Chunki ular xalifa va mamlakatga zarar yetkazish uchun yoshlarni safarbar qilishga eng qodirlaridir, va u yoki bu yo'l bilan odamlar orasiga nifoq solishga ham eng qodirlaridir.", "note": null},
  {"num": 244, "time": "00:18:41,459 --> 00:18:45,419", "arabic": "عَلَى كُلِّ حَالٍ، مَا دَامَ فِي الْأَمْرِ خَيْرٌ لِلْأُمَّةِ", "segs": null, "full_uz": "Har holda, agar bu ishda ummat uchun foyda bo'lsa.", "note": null},
  {"num": 246, "time": "00:18:45,419 --> 00:18:47,979", "arabic": "فَلَنْ أَدَّخِرَ جُهْدًا فِيمَا طُلِبَ مِنِّي", "segs": null, "full_uz": "Mendan so'ralgan narsada hech qanday kuchimni ayamayman.", "note": null},
  {"num": 248, "time": "00:19:37,119 --> 00:19:53,439", "arabic": "أَنَا لَسْتُ خَائِفَةً عَلَيْهِ بِسَبَبِ تَأَخُّرِهِ فِي الرُّجُوعِ إِلَى الْمَنْزِلِ يَا أُمَّ خَالِدٍ", "segs": null, "full_uz": "Men uning uyga kech qaytishidan xavotirlanmayapman, Umm Xolid.", "note": null},
  {"num": 250, "time": "00:19:53,439 --> 00:20:04,199", "arabic": "كُلُّ مَا أَخْشَاهُ أَنْ يَسْتَهْوِيَهُ الْعَمَلُ فَيَنْسَى دُرُوسَهُ، وَيَصْرِفَهُ تَحْصِيلُ الرِّزْقِ عَنْ طَلَبِ الْعِلْمِ بِحُجَّةِ حَاجَتِنَا إِلَى الْمَالِ", "segs": [{"ar": "كُلُّ مَا أَخْشَاهُ أَنْ يَسْتَهْوِيَهُ الْعَمَلُ فَيَنْسَى دُرُوسَهُ", "uz": "faqat qo'rqadigan narsam — ish uni o'ziga tortib, darslarini unutib qo'yishi"}, {"ar": "وَيَصْرِفَهُ تَحْصِيلُ الرِّزْقِ عَنْ طَلَبِ الْعِلْمِ بِحُجَّةِ حَاجَتِنَا إِلَى الْمَالِ", "uz": "va pulga muhtojligimiz bahonasida rizq izlash uni ilm izlashdan chalg'itishi"}], "full_uz": "Faqat qo'rqadigan narsam — ish uni o'ziga tortib, darslarini unutib qo'yishi, va pulga muhtojligimiz bahonasida rizq izlash uni ilm izlashdan chalg'itishi.", "note": null},
  {"num": 254, "time": "00:20:04,199 --> 00:20:06,659", "arabic": "لَنْ يَكُونَ ذَلِكَ بِإِذْنِ اللَّهِ", "segs": null, "full_uz": "Bu bo'lmaydi, Allohning izni bilan.", "note": null},
  {"num": 255, "time": "00:20:06,660 --> 00:20:10,220", "arabic": "فَكُلُّنَا يَعْلَمُ مَا فَعَلْتِهِ مِنْ أَجْلِهِ", "segs": null, "full_uz": "Hammamiz uning uchun nima qilganingizni bilamiz.", "note": null},
  {"num": 256, "time": "00:20:10,220 --> 00:20:14,000", "arabic": "تَهُونُ عَلَيْنَا فِي الْمَعَالِي نُفُوسُنَا يَا أُمَّ خَالِدٍ", "segs": null, "full_uz": "Yuksak maqsadlar yo'lida jonlarimiz ham bizga qadrsiz bo'lib qoladi, Umm Xolid.", "note": "Yuksak maqsad yo'lida shaxsiy manfaat va hatto jonini ham qurbon qilishga tayyorlik haqidagi ibora."},
  {"num": 257, "time": "00:20:14,000 --> 00:20:23,640", "arabic": "وَأَحْمَدُ مَا زَالَ فِي بِدَايَةِ الطَّرِيقِ، وَهُوَ بِحَاجَةٍ دَائِمَةٍ إِلَى مَنْ يُعِينُهُ عَلَى نَوَائِبِ الدَّهْرِ وَيُزِيلُ عَنْهُ عَقَبَاتِ الطَّرِيقِ", "segs": [{"ar": "وَأَحْمَدُ مَا زَالَ فِي بِدَايَةِ الطَّرِيقِ", "uz": "Ahmad hali yo'lning boshida"}, {"ar": "وَهُوَ بِحَاجَةٍ دَائِمَةٍ إِلَى مَنْ يُعِينُهُ عَلَى نَوَائِبِ الدَّهْرِ", "uz": "va unga zamona mashaqqatlariga qarshi doimo yordam beradigan kishi zarur"}, {"ar": "وَيُزِيلُ عَنْهُ عَقَبَاتِ الطَّرِيقِ", "uz": "va yo'lidagi to'siqlarni olib tashlaydigan"}], "full_uz": "Ahmad hali yo'lning boshida, va unga zamona mashaqqatlariga qarshi doimo yordam beradigan hamda yo'lidagi to'siqlarni olib tashlaydigan kishi zarur.", "note": "«نَوَائِبُ الدَّهْرِ» — «zamona ofatlari, taqdir kulfatlari» ma'nosidagi klassik ibora."},
  {"num": 260, "time": "00:20:26,560 --> 00:20:33,800", "arabic": "حَتَّى يَصِلَ إِلَى مَا يَصْبُو إِلَيْهِ، وَلَشَدَّ مَا أَطْمَحُ يَا أُمَّ خَالِدٍ أَنْ أَرَاهُ عَلَمًا مِنْ أَعْلَامِ هَذِهِ الْأُمَّةِ", "segs": [{"ar": "حَتَّى يَصِلَ إِلَى مَا يَصْبُو إِلَيْهِ", "uz": "toki intilgan narsasiga yetguncha"}, {"ar": "وَلَشَدَّ مَا أَطْمَحُ يَا أُمَّ خَالِدٍ أَنْ أَرَاهُ عَلَمًا مِنْ أَعْلَامِ هَذِهِ الْأُمَّةِ", "uz": "va uni shu ummatning peshqadam ulug'laridan biri sifatida ko'rishni qanchalar orzu qilaman, Umm Xolid"}], "full_uz": "Toki intilgan narsasiga yetguncha, va uni shu ummatning peshqadam ulug'laridan biri sifatida ko'rishni qanchalar orzu qilaman, Umm Xolid.", "note": null},
  {"num": 263, "time": "00:20:33,799 --> 00:20:37,220", "arabic": "أَنْتِ لَسْتِ مُقَصِّرَةً فِي حَقِّهِ يَا أُمَّ أَحْمَدَ", "segs": null, "full_uz": "Sen unga bo'lgan burchingda kamchilik qilmading, Umm Ahmad.", "note": null},
  {"num": 264, "time": "00:20:37,220 --> 00:20:43,399", "arabic": "مَا تَفْعَلِينَهُ مِنْ أَجْلِهِ يَعْجِزُ عَنْ فِعْلِهِ الرِّجَالُ الْأَشِدَّاءُ", "segs": null, "full_uz": "Sen uning uchun qilayotgan ishni eng baquvvat erkaklar ham qila olmaydi.", "note": null},
  {"num": 266, "time": "00:20:43,399 --> 00:20:51,659", "arabic": "لَقَدْ نَذَرْتِ عُمْرَكِ وَحَيَاتَكِ وَكُلَّ مَا تَمْلِكِينَهُ حَتَّى أَصْبَحَ رَجُلًا مَلَأَ السَّمْعَ وَالْبَصَرَ", "segs": [{"ar": "لَقَدْ نَذَرْتِ عُمْرَكِ وَحَيَاتَكِ وَكُلَّ مَا تَمْلِكِينَهُ", "uz": "sen umringni, hayotingni va bor-yo'g'ingni bag'ishlading"}, {"ar": "حَتَّى أَصْبَحَ رَجُلًا مَلَأَ السَّمْعَ وَالْبَصَرَ", "uz": "toki u eshitgan-ko'rganlarning yodida qoladigan mashhur inson bo'lguncha"}], "full_uz": "Sen umringni, hayotingni va bor-yo'g'ingni bag'ishlading, toki u eshitgan-ko'rganlarning yodida qoladigan mashhur inson bo'lguncha.", "note": "«مَلَأَ السَّمْعَ وَالْبَصَرَ» — «eshitish va ko'rishni to'ldirmoq», ya'ni juda mashhur va nomi dong taratgan bo'lmoq ma'nosidagi ibora."},
  {"num": 268, "time": "00:20:51,659 --> 00:20:57,559", "arabic": "وَمَعَ ذَلِكَ يَا أُمَّ خَالِدٍ، أَجِدُ نَفْسِي سَبَبًا فِي عَدَمِ تَحْصِيلِهِ الْعِلْمَ", "segs": null, "full_uz": "Shunga qaramay, Umm Xolid, o'zimni uning ilm ololmayotganiga sabab deb bilaman.", "note": null},
  {"num": 270, "time": "00:20:57,559 --> 00:21:05,319", "arabic": "أَنَا مَنْ لَمْ يَنْفَطِرْ قَلْبُهَا عَلَى وَحِيدِهَا، فَتَرَكَتْهُ مُمَزَّقًا بَيْنَ عَمَلِهِ وَعِلْمِهِ", "segs": null, "full_uz": "Men — yakkayu-yagona farzandi uchun yuragi ezilmagan onaman, shuning uchun uni ishi bilan ilmi orasida parchalanib qoldirdim.", "note": "«يَنْفَطِرُ الْقَلْبُ» — «yurak yorilmoq, ezilmoq» — kuchli g'am-tashvish ma'nosidagi majoziy ibora."},
  {"num": 272, "time": "00:21:07,679 --> 00:21:10,059", "arabic": "هَوِّنِي عَلَيْكِ يَا أُمَّ أَحْمَدَ، فَالْأَمْرُ أَبْسَطُ مِمَّا تَتَخَيَّلِينَ", "segs": null, "full_uz": "O'zingga yengil tut, Umm Ahmad, bu ish o'ylaganingdan sodda.", "note": "«هَوِّنْ عَلَيْكَ» — «o'zingga yengil tut, xavotir olma» ma'nosidagi tasalli iborasi."},
  {"num": 274, "time": "00:21:26,000 --> 00:21:28,599", "arabic": "اَلسَّلَامُ عَلَى مَوْلَايَ أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Xo'jayinim, mo'minlar amiriga salom.", "note": null},
  {"num": 275, "time": "00:21:28,599 --> 00:21:30,720", "arabic": "عَلَيْكَ السَّلَامُ يَا يَحْيَى", "segs": null, "full_uz": "Senga ham salom, Yahyo.", "note": null},
  {"num": 276, "time": "00:21:30,720 --> 00:21:45,100", "arabic": "هَذِهِ قَائِمَةٌ بِأَسْمَاءِ الْمُتَآمِرِينَ يَا مَوْلَايَ", "segs": null, "full_uz": "Mana fitnachilarning ismlari ro'yxati, xo'jayinim.", "note": null},
  {"num": 277, "time": "00:21:45,100 --> 00:21:52,299", "arabic": "أَنَا حَصَلْتُ عَلَيْهَا يَا يَحْيَى؟", "segs": null, "full_uz": "Uni men olib berdimmi, Yahyo?", "note": null},
  {"num": 278, "time": "00:21:52,299 --> 00:21:56,180", "arabic": "أَلَمْ أَقُلْ لَكَ يَا مَوْلَايَ إِنَّهَا مَسْأَلَةُ وَقْتٍ", "segs": null, "full_uz": "Sizga aytmaganmidim, xo'jayinim, bu vaqt masalasi ekan?", "note": null},
  {"num": 279, "time": "00:21:56,180 --> 00:21:59,839", "arabic": "وَسَيَعْتَرِفُ ذَلِكَ الْخَائِنُ بِجُرْمِهِ وَشُرَكَائِهِ", "segs": null, "full_uz": "Va o'sha xoin jinoyatini va sheriklarini tan oladi.", "note": null},
  {"num": 280, "time": "00:21:59,839 --> 00:22:13,639", "arabic": "أَوَاثِقٌ أَنْتَ أَنَّهُ لَمْ يُضْمِرْ شَيْئًا وَلَمْ يَكْتُمْ سِرًّا؟", "segs": null, "full_uz": "Sen unga hech narsa yashirmagan va sir tutmaganiga ishonchingiz komilmi?", "note": null},
  {"num": 281, "time": "00:22:13,639 --> 00:22:20,199", "arabic": "أَمَّا عَنِ ابْنِ الْأَيْهَمِ فَأَنَا وَاثِقٌ يَا مَوْلَايَ أَنَّهُ لَمْ يَعْرِفْ أَحَدًا إِلَّا وَأَخْبَرَنَا عَنْهُ", "segs": null, "full_uz": "Ibn al-Ayhamga kelsak, xo'jayinim, u tanigan har bir kishi haqida bizga aytib berganiga ishonaman.", "note": null},
  {"num": 283, "time": "00:22:20,199 --> 00:22:27,039", "arabic": "هَلْ تَخْشَى أَنَّ هُنَاكَ مَنِ اشْتَرَكَ مَعَهُمْ فِي الْمُؤَامَرَةِ وَلَا يَعْرِفُهُ ابْنُ الْأَيْهَمِ؟", "segs": null, "full_uz": "Fitnada ular bilan ishtirok etgan, ammo Ibn al-Ayham bilmaydigan biror kishi bordan qo'rqasanmi?", "note": null},
  {"num": 285, "time": "00:22:27,039 --> 00:22:32,540", "arabic": "حَدَسْتَ مَا فِي نَفْسِي يَا مَوْلَايَ", "segs": null, "full_uz": "Ko'nglimdagini payqadingiz, xo'jayinim.", "note": null},
  {"num": 286, "time": "00:22:32,540 --> 00:22:37,280", "arabic": "وَمَا تَرَاهُ؟", "segs": null, "full_uz": "Sizningcha nima qilish kerak?", "note": null},
  {"num": 287, "time": "00:22:37,280 --> 00:22:45,540", "arabic": "هُمَا أَمْرَانِ يَا مَوْلَايَ، أَوَّلُهُمَا أَنْ نَأْتِيَ بِمَنْ يُقَارِبُونَ ابْنَ الْأَيْهَمِ وَنَضَعَهُمْ أَمَامَ عُيُونِنَا", "segs": [{"ar": "هُمَا أَمْرَانِ يَا مَوْلَايَ", "uz": "ikki narsa bor, xo'jayinim"}, {"ar": "أَوَّلُهُمَا أَنْ نَأْتِيَ بِمَنْ يُقَارِبُونَ ابْنَ الْأَيْهَمِ وَنَضَعَهُمْ أَمَامَ عُيُونِنَا", "uz": "birinchisi, Ibn al-Ayhamga yaqin bo'lganlarni olib kelib, ko'z oldimizda tutishimiz"}], "full_uz": "Ikki narsa bor, xo'jayinim. Birinchisi, Ibn al-Ayhamga yaqin bo'lganlarni olib kelib, ko'z oldimizda tutishimiz.", "note": null},
  {"num": 289, "time": "00:22:45,540 --> 00:22:53,180", "arabic": "لَعَلَّنَا نَعْرِفُ مِنْهُمْ مَا لَمْ يَعْرِفْهُ ابْنُ الْأَيْهَمِ", "segs": null, "full_uz": "Shoyad ulardan Ibn al-Ayham bilmagan narsani bilib olarmiz.", "note": null},
  {"num": 290, "time": "00:22:53,180 --> 00:22:59,779", "arabic": "أَمَّا الْأَمْرُ الثَّانِي يَا مَوْلَايَ، فَهُوَ أَنْ نَأْتِيَ بِيَحْيَى بْنِ عَبْدِ اللَّهِ الطَّالِبِيِّ وَنَضَعَهُ أَمَامَ عُيُونِنَا", "segs": [{"ar": "أَمَّا الْأَمْرُ الثَّانِي يَا مَوْلَايَ", "uz": "ikkinchi narsaga kelsak, xo'jayinim"}, {"ar": "فَهُوَ أَنْ نَأْتِيَ بِيَحْيَى بْنِ عَبْدِ اللَّهِ الطَّالِبِيِّ وَنَضَعَهُ أَمَامَ عُيُونِنَا", "uz": "u Yahyo ibn Abdulloh at-Tolibiyni olib kelib, ko'z oldimizda tutishimizdir"}], "full_uz": "Ikkinchi narsaga kelsak, xo'jayinim, u Yahyo ibn Abdulloh at-Tolibiyni olib kelib, ko'z oldimizda tutishimizdir.", "note": null},
  {"num": 293, "time": "00:23:05,259 --> 00:23:16,220", "arabic": "فَهُوَ كَبِيرُهُمْ، وَمِنْ دُونِهِ لَا يَعْرِفُونَ سَبِيلًا وَلَا يَعْرِفُونَ كَيْفَ يَتَصَرَّفُونَ", "segs": null, "full_uz": "Chunki u ularning boshlig'i — u bo'lmasa, ular na yo'l topadi, na qanday harakat qilishni bilishadi.", "note": null},
  {"num": 294, "time": "00:23:16,220 --> 00:23:20,680", "arabic": "هَذَا رَأْيُ الْحَاذِقِ يَا يَحْيَى", "segs": null, "full_uz": "Bu — ziyrak insonning fikri, Yahyo.", "note": null},
  {"num": 295, "time": "00:23:20,680 --> 00:23:31,140", "arabic": "دَعِ الطَّالِبِيَّ تَحْتَ عَيْنِ ابْنِكَ، وَاسْتَأْصِلْ شَأْفَةَ هَؤُلَاءِ الْمَارِقِينَ، اَلْغَفْلَةُ مَقْتَلُ اللَّبِيبِ يَا يَحْيَى", "segs": [{"ar": "دَعِ الطَّالِبِيَّ تَحْتَ عَيْنِ ابْنِكَ", "uz": "at-Tolibiyni o'g'ling nazorati ostida qoldir"}, {"ar": "وَاسْتَأْصِلْ شَأْفَةَ هَؤُلَاءِ الْمَارِقِينَ", "uz": "va bu isyonchilarni ildizi bilan qo'porib tashla"}, {"ar": "اَلْغَفْلَةُ مَقْتَلُ اللَّبِيبِ يَا يَحْيَى", "uz": "g'aflat — aqllining halokati, Yahyo"}], "full_uz": "At-Tolibiyni o'g'ling nazorati ostida qoldir, va bu isyonchilarni ildizi bilan qo'porib tashla — g'aflat aqllining halokatidir, Yahyo.", "note": "«اِسْتَأْصَلَ شَأْفَتَهُ» — «ildizi bilan qo'poriб tashlamoq», ya'ni butunlay yo'q qilish ma'nosidagi ibora. «الْغَفْلَةُ مَقْتَلُ اللَّبِيبِ» — mashhur hikmatli gap: hatto eng aqlli inson ham beparvolik tufayli halok bo'lishi mumkin."},
  {"num": 298, "time": "00:23:34,100 --> 00:23:36,900", "arabic": "جَعْفَرٌ وَأَبُو جَعْفَرٍ", "segs": null, "full_uz": "Ja'far va Abu Ja'far!", "note": null},
  {"num": 299, "time": "00:23:36,900 --> 00:23:42,560", "arabic": "طَوْعَ بَنَانِكَ يَا مَوْلَايَ", "segs": null, "full_uz": "Buyrug'ingizga bo'ysunamiz, xo'jayinim.", "note": "«طَوْعَ بَنَانِهِ» — «barmog'iga bo'ysungan», ya'ni to'liq itoatkorlik, biror kishining har bir ishorasiga qulog'i og'ib turish ma'nosidagi ibora."},
  {"num": 300, "time": "00:23:42,560 --> 00:23:45,980", "arabic": "تَأَخَّرْتَ يَا وَلَدِي", "segs": null, "full_uz": "Kechikding, o'g'lim.", "note": null},
  {"num": 301, "time": "00:23:45,980 --> 00:23:46,799", "arabic": "أَعْتَذِرُ عَنْ تَأَخُّرِي يَا أُمِّي", "segs": null, "full_uz": "Kechikkanim uchun uzr, onajon.", "note": null},
  {"num": 302, "time": "00:23:46,799 --> 00:23:48,779", "arabic": "لَا عَلَيْكَ", "segs": null, "full_uz": "Xavotir olma.", "note": null},
  {"num": 303, "time": "00:23:48,779 --> 00:23:51,480", "arabic": "مَا بِكَ يَا وَلَدِي؟", "segs": null, "full_uz": "Senga nima bo'ldi, o'g'lim?", "note": null},
  {"num": 304, "time": "00:23:51,480 --> 00:23:52,639", "arabic": "لِمَ أَنْتَ جَهْمُ الْوَجْهِ؟", "segs": null, "full_uz": "Nega yuzing bunchalik ekshigan?", "note": null},
  {"num": 305, "time": "00:23:52,639 --> 00:23:54,420", "arabic": "لَا شَيْءَ", "segs": null, "full_uz": "Hech narsa.", "note": null},
  {"num": 306, "time": "00:23:54,420 --> 00:23:56,519", "arabic": "عُذْرًا قَطَعْتُ عَلَيْكَ نَوْمَكَ", "segs": null, "full_uz": "Uzr, uyqungni bo'ldim.", "note": null},
  {"num": 307, "time": "00:23:56,519 --> 00:23:59,980", "arabic": "وَأَنَّى لِيَ النَّوْمُ وَأَنْتَ غَائِبٌ؟", "segs": null, "full_uz": "Sen yo'q ekaning, uyqu qayoqda menga?", "note": null},
  {"num": 308, "time": "00:23:59,980 --> 00:24:01,980", "arabic": "لَمْ تَقُلْ لِي لِمَاذَا تَأَخَّرْتَ؟", "segs": null, "full_uz": "Nega kechikkaningni aytmading-ku?", "note": null},
  {"num": 309, "time": "00:24:01,980 --> 00:24:04,920", "arabic": "سَأُخْبِرُكِ بِذَلِكَ لَاحِقًا", "segs": null, "full_uz": "Buni senga keyinroq aytib beraman.", "note": null},
  {"num": 310, "time": "00:24:04,920 --> 00:24:18,779", "arabic": "إِذَنِ ائْذَنِي لِي، فَأَنَا مُتْعَبٌ وَأُرِيدُ أَنْ أَخْلُدَ إِلَى النَّوْمِ", "segs": null, "full_uz": "Unda menga ruxsat ber, charchadim va uxlashni istayman.", "note": "«يَخْلُدُ إِلَى النَّوْمِ» — «uyquga cho'kmoq, uxlashga o'tmoq» ma'nosidagi ibora."},
  {"num": 311, "time": "00:24:18,779 --> 00:24:23,960", "arabic": "مَا بِكَ يَا وَلَدِي؟ أَتَشْكُو مِنْ شَيْءٍ؟", "segs": null, "full_uz": "Senga nima bo'ldi, o'g'lim? Biror narsadan shikoyating bormi?", "note": null},
  {"num": 313, "time": "00:24:23,960 --> 00:24:29,119", "arabic": "لَا يَا أُمِّي، إِنَّمَا هُوَ أَمْرٌ أُرِيدُ أَنْ أَتَثَبَّتَ مِنْهُ أَوَّلًا", "segs": null, "full_uz": "Yo'q, onajon, faqat bir masala bor, avval uni aniqlashtirmoqchiman.", "note": null},
  {"num": 315, "time": "00:24:29,119 --> 00:24:30,619", "arabic": "وَسَأُخْبِرُكِ بِهِ إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Alloh xohlasa, senga aytib beraman.", "note": null},
  {"num": 316, "time": "00:24:30,619 --> 00:24:31,720", "arabic": "لَا تَقْلَقِي", "segs": null, "full_uz": "Xavotir olma.", "note": null},
  {"num": 317, "time": "00:24:31,720 --> 00:24:36,740", "arabic": "اَلْآنَ أَنَا مُتْعَبٌ قَلِيلًا وَأُرِيدُ أَنْ أَنَامَ", "segs": null, "full_uz": "Hozir bir oz charchaganman va uxlashni istayman.", "note": null},
  {"num": 318, "time": "00:24:36,740 --> 00:24:41,480", "arabic": "تُصْبِحِينَ عَلَى خَيْرٍ", "segs": null, "full_uz": "Xayrli tun (qizga).", "note": null},
  {"num": 319, "time": "00:24:48,779 --> 00:25:18,759", "arabic": "تُصْبِحُ عَلَى خَيْرٍ", "segs": null, "full_uz": "Xayrli tun (yigitga).", "note": null},
  {"num": 321, "time": "00:25:18,779 --> 00:25:24,339", "arabic": "فَوْزُ، هُوَ اسْمُكِ عَلَى مَا أَظُنُّ", "segs": null, "full_uz": "Favz, ismingcha, agar to'g'ri o'ylasam.", "note": null},
  {"num": 323, "time": "00:25:24,339 --> 00:25:26,940", "arabic": "هَا قَدْ عَرَفْنَا عَنْكِ شَيْئًا", "segs": null, "full_uz": "Mana, sen haqingda bir narsani bilib oldik.", "note": null},
  {"num": 324, "time": "00:25:26,940 --> 00:25:33,480", "arabic": "هَذَا الْمِشْطُ لِي، وَمِنْ حَقِّي، مَالِي مَالِي", "segs": null, "full_uz": "Bu taroq meniki, va bu mening haqqim — mening mulkim, mening mulkim.", "note": null},
  {"num": 325, "time": "00:25:33,480 --> 00:25:37,779", "arabic": "أَنْتِ وَكُلُّ مَا تَمْلِكِينَ مِلْكٌ لِي، فَهِمْتِ؟", "segs": null, "full_uz": "Sen va sening bor-yo'g'ing menga tegishli, tushundingmi?", "note": null},
  {"num": 327, "time": "00:25:36,680 --> 00:25:38,779", "arabic": "مَا قِصَّةُ هَذَا الْمِشْطِ؟", "segs": null, "full_uz": "Bu tarokning tarixi nima?", "note": null},
  {"num": 328, "time": "00:25:38,779 --> 00:25:40,099", "arabic": "وَمَا تَعْنِيكِ قِصَّتُهُ؟", "segs": null, "full_uz": "Uning tarixi senga nima daxli bor?", "note": null},
  {"num": 329, "time": "00:25:40,099 --> 00:25:41,960", "arabic": "جَاوِبِي عَلَى قَدْرِ السُّؤَالِ", "segs": null, "full_uz": "Savolga mos javob ber.", "note": null},
  {"num": 331, "time": "00:25:45,920 --> 00:25:52,899", "arabic": "هِيَ هَدِيَّةٌ مِنْ أَبِي، قَدْ صَنَعَهُ بِيَدِهِ", "segs": null, "full_uz": "Bu — otamning sovg'asi, uni o'z qo'li bilan yasagan.", "note": null},
  {"num": 333, "time": "00:25:52,899 --> 00:25:57,779", "arabic": "أَعْطِنِي إِيَّاهُ", "segs": null, "full_uz": "Uni menga ber.", "note": null},
  {"num": 334, "time": "00:25:57,720 --> 00:26:03,619", "arabic": "سَأَحْتَفِظُ بِهِ إِلَى أَنْ يَلِينَ رَأْيُكِ، وَإِنْ أَحْسَنْتِ التَّصَرُّفَ سَأُعِيدُهُ إِلَيْكِ", "segs": [{"ar": "سَأَحْتَفِظُ بِهِ إِلَى أَنْ يَلِينَ رَأْيُكِ", "uz": "fikring yumshaguncha uni saqlab qo'yaman"}, {"ar": "وَإِنْ أَحْسَنْتِ التَّصَرُّفَ سَأُعِيدُهُ إِلَيْكِ", "uz": "va agar yaxshi xulq ko'rsatsang, uni senga qaytaraman"}], "full_uz": "Fikring yumshaguncha uni saqlab qo'yaman, va agar yaxshi xulq ko'rsatsang, uni senga qaytaraman.", "note": null},
  {"num": 336, "time": "00:26:03,619 --> 00:26:12,759", "arabic": "لَيْسَ هَذَا فَقَطْ، بَلْ سَأَجْعَلُكِ تَعِيشِينَ نَعِيمًا لَمْ تَعْرِفِيهِ مِنْ قَبْلُ", "segs": null, "full_uz": "Bu bilan cheklanmayman, seni ilgari bilmagan ne'matda yashataman.", "note": null},
  {"num": 338, "time": "00:26:12,759 --> 00:26:15,039", "arabic": "اَلْمُهِمُّ أَنْ تُحْسِنِي سُلُوكَكِ أَمَامَ مَنْ سَيَشْتَرِيكِ", "segs": null, "full_uz": "Muhimi — seni sotib oladigan kishi oldida o'zingni yaxshi tutishing.", "note": null},
  {"num": 339, "time": "00:26:15,039 --> 00:26:15,920", "arabic": "أَنَا لَسْتُ جَارِيَةً، أَنَا حُرَّةٌ", "segs": null, "full_uz": "Men cho'ri emasman, men erkinman.", "note": null},
  {"num": 341, "time": "00:26:15,920 --> 00:26:24,279", "arabic": "وَالْحُرُّ لَا يُبَاعُ وَلَا يُشْتَرَى بِكُنُوزِ الدُّنْيَا كُلِّهَا، هَلْ فَهِمْتِ؟ سَأَبْقَى حُرَّةً", "segs": [{"ar": "وَالْحُرُّ لَا يُبَاعُ وَلَا يُشْتَرَى بِكُنُوزِ الدُّنْيَا كُلِّهَا", "uz": "erkin inson dunyoning bor xazinasiga ham sotilmaydi va sotib olinmaydi"}, {"ar": "هَلْ فَهِمْتِ؟ سَأَبْقَى حُرَّةً", "uz": "tushundingmi? Men erkin bo'lib qolaman"}], "full_uz": "Erkin inson dunyoning bor xazinasiga ham sotilmaydi va sotib olinmaydi. Tushundingmi? Men erkin bo'lib qolaman.", "note": null},
  {"num": 343, "time": "00:26:24,279 --> 00:26:29,120", "arabic": "اَلْأَيَّامُ بَيْنَنَا يَا فَوْزُ، اَلْأَيَّامُ بَيْنَنَا", "segs": null, "full_uz": "Kunlar hukm qiladi, Favz, kunlar hukm qiladi.", "note": "«الأيام بيننا» — «kunlar oramizda [hakam bo'ladi]», ya'ni vaqt haq bilan nohaqni ko'rsatadi ma'nosidagi majoziy ibora."},
  {"num": 345, "time": "00:26:29,200 --> 00:26:32,620", "arabic": "مَا زِلْتُ إِلَى هَذِهِ اللَّحْظَةِ أُعَامِلُكِ بِاللِّينِ، وَلَكِنَّ الْأَيَّامَ الْقَادِمَةَ سَتَرَيْنَ مِنِّي مَا لَمْ تَعْرِفِيهِ", "segs": null, "full_uz": "Hozirgacha senga yumshoqlik bilan muomala qilib keldim, lekin kelgusi kunlarda mendan ko'rmagan narsalaringni ko'rasan.", "note": null},
  {"num": 347, "time": "00:26:32,620 --> 00:26:36,320", "arabic": "تَعَالَ", "segs": null, "full_uz": "Kel bu yoqqa.", "note": null},
  {"num": 348, "time": "00:26:36,320 --> 00:26:38,320", "arabic": "اِفْعَلْ بِي مَا تَشَاءُ", "segs": null, "full_uz": "Menga xohlaganingni qil.", "note": null},
  {"num": 349, "time": "00:26:38,320 --> 00:26:45,920", "arabic": "أَنَا حُرَّةٌ! حُرَّةٌ!", "segs": null, "full_uz": "Men erkinman! Erkinman!", "note": null},
  {"num": 351, "time": "00:26:45,920 --> 00:26:53,759", "arabic": "وَمَا الْمُشْكِلُ فِيمَا سَمِعْتَ يَا أَحْمَدُ؟ أَلَيْسَ مِنْ مَهَامِ الْوُلَاةِ وَالْعُمَّالِ مَعْرِفَةُ كُلِّ كَبِيرَةٍ وَصَغِيرَةٍ", "segs": [{"ar": "وَمَا الْمُشْكِلُ فِيمَا سَمِعْتَ يَا أَحْمَدُ؟", "uz": "eshitganingda nima yomonlik bor, Ahmad?"}, {"ar": "أَلَيْسَ مِنْ مَهَامِ الْوُلَاةِ وَالْعُمَّالِ مَعْرِفَةُ كُلِّ كَبِيرَةٍ وَصَغِيرَةٍ", "uz": "voliy va amaldorlarning vazifasi har bir kichik-yu katta narsani bilish emasmi"}], "full_uz": "Eshitganingda nima yomonlik bor, Ahmad? Voliy va amaldorlarning vazifasi har bir kichik-yu katta narsani bilish emasmi.", "note": null},
  {"num": 353, "time": "00:26:53,759 --> 00:27:03,240", "arabic": "فِي دَوْلَةِ الْخِلَافَةِ الَّتِي يَتَرَبَّصُ بِهَا الْخَارِجُونَ وَالْمَارِقُونَ مِنْ كُلِّ حَجْمٍ وَصَوْتٍ، وَمَا فَعَلَ ذَلِكَ إِلَّا لِحِفْظِ الدِّينِ وَالدُّنْيَا مِنَ الْحَاقِدِينَ وَأَهْلِ الْفِتَنِ", "segs": [{"ar": "فِي دَوْلَةِ الْخِلَافَةِ الَّتِي يَتَرَبَّصُ بِهَا الْخَارِجُونَ وَالْمَارِقُونَ مِنْ كُلِّ حَجْمٍ وَصَوْتٍ", "uz": "har xil kattalik va ovozdagi isyonchi va mo'tadillar poylab turgan xalifalik davlatida"}, {"ar": "وَمَا فَعَلَ ذَلِكَ إِلَّا لِحِفْظِ الدِّينِ وَالدُّنْيَا مِنَ الْحَاقِدِينَ وَأَهْلِ الْفِتَنِ", "uz": "va u buni faqat dinu-dunyoni kek saqlovchi va fitnachilardan himoya qilish uchun qildi"}], "full_uz": "Har xil kattalik va ovozdagi isyonchi va mo'tadillar poylab turgan xalifalik davlatida, u buni faqat dinu-dunyoni kek saqlovchi va fitnachilardan himoya qilish uchun qildi.", "note": null},
  {"num": 355, "time": "00:27:03,240 --> 00:27:14,940", "arabic": "ثُمَّ أَنَا مِنْ وَاجِبِي وَوَاجِبِ غَيْرِي أَيْضًا أَنْ نُسَاعِدَهُمْ عَلَى حِفْظِ أَمْنِ وَأَمَانِ الْبِلَادِ", "segs": null, "full_uz": "Bundan tashqari, mening ham, boshqalarning ham burchi — ularga mamlakat xavfsizligini saqlashda yordam berishdir.", "note": null},
  {"num": 356, "time": "00:27:14,940 --> 00:27:18,160", "arabic": "لَا أَدْرِي، عَسَى أَنْ يَكُونَ كَلَامُكَ صَحِيحًا", "segs": null, "full_uz": "Bilmadim, balki gaping to'g'ridir.", "note": null},
  {"num": 357, "time": "00:27:18,160 --> 00:27:20,460", "arabic": "لَا عَلَيْكَ أَنْتَ يَا أَحْمَدُ، دَعِ الدَّوْلَةَ أُمُورَ لِرِجَالِهَا", "segs": null, "full_uz": "Sen xavotir olma, Ahmad, davlat ishlarini o'z ahliga qo'y.", "note": null},
  {"num": 359, "time": "00:27:20,460 --> 00:27:24,519", "arabic": "أَمْرُ الدَّوْلَةِ بَعْضُ أُمُورِنَا يَا عَمَّاهُ، أَحْمَدُ", "segs": null, "full_uz": "Davlat ishi ham bizning ishimizning bir qismi-ku, amakijon. Ahmad!", "note": null},
  {"num": 361, "time": "00:27:24,519 --> 00:27:28,799", "arabic": "لَا أَقْدِرُ عَلَى حِجَاجِكَ قَبْلَ أَنْ تَفْهَمَ", "segs": null, "full_uz": "Sen tushunib yetmagunicha, munozaralaringga bardosh bera olmayman.", "note": null},
  {"num": 363, "time": "00:27:28,799 --> 00:27:35,200", "arabic": "خُذْ كِتَابِي هَذَا وَأَوْدِعْهُ فِي طَرِيقِكَ دِيوَانَ الْوَالِي", "segs": null, "full_uz": "Bu maktubimni olib, yo'lingda voliy devoniga topshir.", "note": null},
  {"num": 364, "time": "00:27:35,200 --> 00:27:37,240", "arabic": "خَيْرًا إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Alloh xohlasa, hayrli bo'lsin.", "note": null},
  {"num": 365, "time": "00:27:37,240 --> 00:27:38,320", "arabic": "مَا الْأَمْرُ؟", "segs": null, "full_uz": "Nima gap?", "note": null},
  {"num": 366, "time": "00:27:38,320 --> 00:27:40,940", "arabic": "لَا عَلَيْكِ يَا أُمَّاهُ، أُودِعُهُ فِي الدِّيوَانِ وَحَسْبُ", "segs": null, "full_uz": "Xavotir olma, onajon, uni faqat devonga topshiraman xolos.", "note": null},
  {"num": 368, "time": "00:27:40,940 --> 00:27:44,320", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Sizga salom.", "note": null},
  {"num": 369, "time": "00:27:44,319 --> 00:27:45,679", "arabic": "وَعَلَيْكُمُ السَّلَامُ", "segs": null, "full_uz": "Sizga ham salom.", "note": null},
  {"num": 371, "time": "00:28:15,680 --> 00:28:18,920", "arabic": "غَفَرَ اللَّهُ لَكَ يَا عَمِّ", "segs": null, "full_uz": "Alloh sizni kechirsin, amaki.", "note": null},
  {"num": 372, "time": "00:28:18,920 --> 00:28:22,560", "arabic": "مَا شَأْنِي أَنَا بِالْوَالِي؟", "segs": null, "full_uz": "Voliy bilan mening nima ishim bor?", "note": null},
  {"num": 373, "time": "00:28:22,560 --> 00:28:40,640", "arabic": "أَتَعْلَمُ أَنَّ مَنْ يُعِينُ الظَّالِمَ فَهُوَ ظَالِمٌ مِثْلُهُ؟", "segs": null, "full_uz": "Bilasanmi, zolimga yordam bergan kishi ham xuddi shunday zolim bo'ladi?", "note": "Bu — «Zolimga yordam bergan uning [gunohiga] shserik bo'ladi» mazmunidagi diniy-axloqiy qoidaga ishora."},
  {"num": 375, "time": "00:28:40,640 --> 00:28:40,980", "arabic": "أَعْلَمُ", "segs": null, "full_uz": "Bilaman.", "note": null},
  {"num": 376, "time": "00:28:40,980 --> 00:28:44,920", "arabic": "حَسِبْتُكَ لَا تَعْلَمُ", "segs": null, "full_uz": "Bilmaysan deb o'ylagandim.", "note": null},
  {"num": 377, "time": "00:28:44,920 --> 00:29:11,740", "arabic": "رُبَّمَا كَانَ لِعَمِّكَ الْعُذْرُ فِيمَا يَفْعَلُهُ", "segs": null, "full_uz": "Balki amakingning qilayotgan ishida uzri bordir.", "note": null},
  {"num": 378, "time": "00:29:11,740 --> 00:29:18,579", "arabic": "إِذْ يَرَى أَنَّهُ بِذَلِكَ يَنْصَحُ الْوُلَاةَ وَيُنَبِّهُهُمْ إِلَى خَطَرٍ هُوَ يَرَى", "segs": null, "full_uz": "Chunki u shu bilan hukmdorlarga nasihat qilib, o'zi ko'rgan xavf haqida ularni ogohlantirmoqchi ekan deb o'ylaydi.", "note": null},
  {"num": 379, "time": "00:29:18,579 --> 00:29:23,220", "arabic": "وَلَكِنْ أَنْتَ لَا شَأْنَ لَكَ بِذَلِكَ يَا وَالِدِي", "segs": null, "full_uz": "Lekin sening bunga aloqang yo'q-ku, otajon.", "note": null},
  {"num": 380, "time": "00:29:23,220 --> 00:29:30,319", "arabic": "أَجَلْ يَا أُمِّي، وَلَوْلَا كَرَاهَةٌ فِي نَفْسِي أَجِدُهَا لَمَا تَرَكْتُ الْكِتَابَ عِنْدِي وَلَمْ أُوصِلْهُ إِلَى الْوَالِي كَمَا طَلَبَ عَمِّي", "segs": [{"ar": "أَجَلْ يَا أُمِّي، وَلَوْلَا كَرَاهَةٌ فِي نَفْسِي أَجِدُهَا", "uz": "ha, onajon, agar ichimda his qilayotgan bir istihola bo'lmaganida"}, {"ar": "لَمَا تَرَكْتُ الْكِتَابَ عِنْدِي وَلَمْ أُوصِلْهُ إِلَى الْوَالِي كَمَا طَلَبَ عَمِّي", "uz": "amakim so'ragandek maktubni saqlab qolib, voliyga yetkazmasdim"}], "full_uz": "Ha, onajon, agar ichimda his qilayotgan bir istihola bo'lmaganida, amakim so'ragandek maktubni saqlab qolib, voliyga yetkazmasdim.", "note": null},
  {"num": 382, "time": "00:29:37,319 --> 00:29:39,579", "arabic": "هَلْ قَرَأْتَ مَا فِي الْكِتَابِ؟", "segs": null, "full_uz": "Maktubdagini o'qidingmi?", "note": null},
  {"num": 383, "time": "00:29:39,579 --> 00:29:43,899", "arabic": "أَعُوذُ بِاللَّهِ أَنْ أَفْعَلَ ذَلِكَ، إِنَّهُ أَمَانَةٌ وَلَا يَجُوزُ فَتْحُهَا", "segs": null, "full_uz": "Bunday qilishdan Allohga sig'inaman, u — omonat, uni ochish joiz emas.", "note": null},
  {"num": 385, "time": "00:29:43,899 --> 00:29:49,179", "arabic": "أَحْسَنْتَ، وَبَارَكَ اللَّهُ بِكَ يَا وَلَدِي", "segs": null, "full_uz": "Barakalla, Alloh senga baraka bersin, o'g'lim.", "note": null},
  {"num": 387, "time": "00:29:49,179 --> 00:29:52,319", "arabic": "وَلَكِنْ قَدْ يُعْرَفُ الْكِتَابُ مِنْ عُنْوَانِهِ", "segs": null, "full_uz": "Lekin maktubning mazmuni uning sarlavhasidan bilinib qolishi mumkin.", "note": null},
  {"num": 388, "time": "00:29:52,319 --> 00:29:56,319", "arabic": "لَا بُدَّ أَنَّ فِي الْكِتَابِ أَخْبَارَ السُّوقِ وَالْعُلَمَاءِ أَرْسَلَهَا عَمِّي إِلَى الْوَالِي", "segs": null, "full_uz": "Maktubda amakim voliyga yuborgan bozor va olimlar haqidagi xabarlar bo'lishi shubhasiz.", "note": null},
  {"num": 389, "time": "00:29:56,319 --> 00:30:05,879", "arabic": "وَمَا تَرَى بِشَأْنِ الْكِتَابِ؟", "segs": null, "full_uz": "Maktub haqida qanday fikrdasan?", "note": null},
  {"num": 390, "time": "00:30:05,879 --> 00:30:09,539", "arabic": "أَرَى أَنْ أُعِيدَهُ إِلَى عَمِّي وَأُخْبِرَهُ أَنْ لَا شَأْنَ لِي بِذَلِكَ", "segs": null, "full_uz": "Fikrimcha, uni amakimga qaytarib, bunga aloqam yo'qligini aytishim kerak.", "note": null},
  {"num": 391, "time": "00:30:09,539 --> 00:30:16,960", "arabic": "كَمَا أَنَّنِي سَأَتْرُكُ الْعَمَلَ فِي بَيْتِ الْحِكْمَةِ لِأَنَّنِي لَنْ أَسْتَطِيعَ أَنْ أُوَفِّقَ بَيْنَ الْعَمَلِ وَطَلَبِي لِلْعِلْمِ", "segs": null, "full_uz": "Shuningdek, Baytul-Hikmadagi ishimni tashlab qo'yaman, chunki ish bilan ilm izlashimni muvofiqlashtira olmayman.", "note": null},
  {"num": 393, "time": "00:30:16,960 --> 00:30:21,619", "arabic": "أَمَّا أَنَا، فَلِي رَأْيٌ آخَرُ بِشَأْنِهِ", "segs": null, "full_uz": "Menga kelsak, bu haqda boshqacha fikrim bor.", "note": null},
  {"num": 395, "time": "00:30:21,619 --> 00:30:39,539", "arabic": "مَا هُوَ؟", "segs": null, "full_uz": "U nima?", "note": null},
  {"num": 396, "time": "00:31:02,299 --> 00:31:05,440", "arabic": "إِلَى مَتَى سَتَبْقَى هَكَذَا يَا فَرَجُ؟", "segs": null, "full_uz": "Qachongacha shunday yashaysan, Faraj?", "note": null},
  {"num": 397, "time": "00:31:05,440 --> 00:31:08,440", "arabic": "اَلْخَوْفُ يَسْكُنُكَ وَالْعَوَزُ لَا يُفَارِقُكَ أَبَدًا", "segs": null, "full_uz": "Qo'rquv sen bilan yashaydi, muhtojlik esa hech qachon seni tark etmaydi.", "note": null},
  {"num": 398, "time": "00:31:16,440 --> 00:31:17,440", "arabic": "أَلَيْسَ مِنْ أَمَلٍ فِي تَغْيِيرِ حَالِكَ؟", "segs": null, "full_uz": "Holingni o'zgartirishga umid yo'qmi?", "note": null},
  {"num": 399, "time": "00:31:19,440 --> 00:31:20,440", "arabic": "مَنْ هَذَا؟", "segs": null, "full_uz": "Bu kim?", "note": null},
  {"num": 400, "time": "00:31:21,440 --> 00:31:22,440", "arabic": "بُهْلُولٌ", "segs": null, "full_uz": "Buhlul.", "note": null},
  {"num": 401, "time": "00:31:23,440 --> 00:31:25,440", "arabic": "أَهْلًا أَهْلًا", "segs": null, "full_uz": "Xush kelibsan, xush kelibsan.", "note": null},
  {"num": 402, "time": "00:31:26,440 --> 00:31:28,440", "arabic": "تَعَالَ إِلَى النَّارِ اسْتَدْفِئْ", "segs": null, "full_uz": "Olov yoniga kel, isin.", "note": null},
  {"num": 403, "time": "00:31:28,440 --> 00:31:30,440", "arabic": "هَيَّا هَاكَ يَا ابْنَ أُمِّي فَرَجُ", "segs": null, "full_uz": "Kel bu yoqqa, jonim Faraj.", "note": null},
  {"num": 404, "time": "00:31:32,440 --> 00:31:33,440", "arabic": "تَدْعُونِي إِلَى النَّارِ؟", "segs": null, "full_uz": "Meni olovga chaqiryapsizmi?", "note": null},
  {"num": 405, "time": "00:31:33,440 --> 00:31:37,340", "arabic": "هَذَا هُوَ بُهْلُولٌ", "segs": null, "full_uz": "Mana shu Buhlul.", "note": null},
  {"num": 407, "time": "00:31:37,340 --> 00:31:42,080", "arabic": "يَا بُهْلُولُ، وَهَلْ نَحْنُ فِي يَوْمِ الْقِيَامَةِ حَتَّى تَخْشَى دَعْوَتِي؟", "segs": null, "full_uz": "Ey Buhlul, qiyomat kunidamizmi, taklifimdan qo'rqasan?", "note": null},
  {"num": 409, "time": "00:31:42,080 --> 00:31:46,860", "arabic": "مَنْ يَنْظُرْ لِمَوْطِئِ قَدَمَيْهِ يَخِرَّ سَاقِطًا", "segs": null, "full_uz": "Faqat oyog'i ostiga qaraydigan yiqilib tushadi.", "note": "Bu — hayotiy hikmat: faqat kichik, yaqin narsalarga qaraydigan kishi, katta maqsadni ko'rmay adashadi degan majoziy ma'noni bildiradi."},
  {"num": 411, "time": "00:31:46,860 --> 00:31:51,660", "arabic": "وَمَنْ يَنْظُرْ إِلَى الْأَمَامِ يَصِلْ سَالِمًا", "segs": null, "full_uz": "Oldinga qaraydigan esa omon-eson yetib boradi.", "note": null},
  {"num": 413, "time": "00:31:51,660 --> 00:31:54,279", "arabic": "لَمْ أَفْهَمْ", "segs": null, "full_uz": "Tushunmadim.", "note": null},
  {"num": 414, "time": "00:31:54,279 --> 00:31:57,480", "arabic": "مَاذَا تَقْصِدُ؟", "segs": null, "full_uz": "Nimani nazarda tutyapsan?", "note": null},
  {"num": 415, "time": "00:31:57,480 --> 00:31:59,440", "arabic": "لِأَنَّكَ تُحِبُّ النَّظَرَ إِلَى مَوْطِئِ قَدَمَيْكَ", "segs": null, "full_uz": "Chunki sen o'z oyog'ing ostiga qarashni yoqtirasan.", "note": null},
  {"num": 416, "time": "00:32:03,440 --> 00:32:05,440", "arabic": "اَللَّهُمَّ ثَبِّتْنَا عَلَى الْعَقْلِ وَالدِّينِ، آمِينَ", "segs": null, "full_uz": "Yo Alloh, bizni aql va dinda mustahkam qil, omin.", "note": null},
  {"num": 418, "time": "00:32:29,440 --> 00:32:38,259", "arabic": "مَنْ يَنْظُرْ إِلَى مَوْطِئِ قَدَمَيْهِ يَقَعْ", "segs": null, "full_uz": "Oyog'i ostiga qaraydigan yiqiladi.", "note": null},
  {"num": 419, "time": "00:32:38,259 --> 00:32:50,700", "arabic": "وَأَنْتَ يَا فَرَجُ تُحِبُّ النَّظَرَ إِلَى مَوْطِئِ قَدَمَيْكَ", "segs": null, "full_uz": "Sen esa, Faraj, oyog'ing ostiga qarashni yoqtirasan.", "note": null},
  {"num": 420, "time": "00:32:50,700 --> 00:32:52,840", "arabic": "لَعَلَّكَ عَلَى حَقٍّ يَا بُهْلُولُ", "segs": null, "full_uz": "Balki haqsan, Buhlul.", "note": null},
  {"num": 421, "time": "00:32:56,779 --> 00:32:58,220", "arabic": "أَيْنَ الْكِتَابُ يَا أَحْمَدُ؟", "segs": null, "full_uz": "Maktub qayerda, Ahmad?", "note": null},
  {"num": 422, "time": "00:32:58,220 --> 00:32:59,960", "arabic": "قَدْ أَلْقَيْتُهُ فِي النَّهْرِ", "segs": null, "full_uz": "Uni daryoga tashladim.", "note": null},
  {"num": 423, "time": "00:32:59,960 --> 00:33:01,480", "arabic": "مَاذَا؟", "segs": null, "full_uz": "Nima?!", "note": null},
  {"num": 424, "time": "00:33:01,480 --> 00:33:06,220", "arabic": "أَلْقَيْتُهُ فِي النَّهْرِ يَا عَمَّاهُ", "segs": null, "full_uz": "Uni daryoga tashladim, amaki.", "note": null},
  {"num": 425, "time": "00:33:07,480 --> 00:33:10,220", "arabic": "مَا الَّذِي حَمَلَكَ عَلَى فِعْلِ ذَلِكَ؟", "segs": null, "full_uz": "Bu ishni qilishga seni nima majbur qildi?", "note": null},
  {"num": 426, "time": "00:33:10,220 --> 00:33:11,819", "arabic": "أَمْ لَعَلَّكَ ظَنَنْتَ أَنِّي أَبِيعُ دِينِي بِدُنْيَايَ؟", "segs": null, "full_uz": "Yoki dinimni dunyoyimga sotaman deb o'yladingmi?", "note": null},
  {"num": 427, "time": "00:33:11,819 --> 00:33:13,299", "arabic": "إِنَّمَا أَنَا أَسْعَى يَا أَحْمَدُ", "segs": null, "full_uz": "Men faqat harakat qilyapman, Ahmad.", "note": null},
  {"num": 428, "time": "00:33:13,299 --> 00:33:15,420", "arabic": "أَعْرِفُ غَايَاتِكَ يَا عَمِّ", "segs": null, "full_uz": "Niyatlaringni bilaman, amaki.", "note": null},
  {"num": 429, "time": "00:33:15,420 --> 00:33:19,079", "arabic": "اِغْفِرْ لِي مَا قَدَّمْتُ", "segs": null, "full_uz": "Qilgan ishim uchun meni kechir.", "note": null},
  {"num": 430, "time": "00:33:28,220 --> 00:33:40,220", "arabic": "وَلَكِنِّي أَرَى أَسْبَابًا لِخِدْمَةِ الرَّعِيَّةِ سِوَى مَا تَرَى أَنْتَ", "segs": null, "full_uz": "Lekin men xalqqa xizmat qilishning senga ko'rinmagan boshqa sabablarini ko'ryapman.", "note": null},
  {"num": 431, "time": "00:33:40,220 --> 00:33:42,740", "arabic": "هَلْ يَلْزَمُكَ عَامِلٌ؟", "segs": null, "full_uz": "Ishchi kerakmi?", "note": null},
  {"num": 432, "time": "00:33:42,740 --> 00:33:43,779", "arabic": "لَيْسَ لَدَيَّ عَمَلٌ لِلُصُوصٍ مِنْ أَمْثَالِكَ", "segs": null, "full_uz": "Sendaqa o'g'rilarga ish yo'q menda.", "note": null},
  {"num": 433, "time": "00:33:43,779 --> 00:33:45,140", "arabic": "اِنْصَرِفْ مِنْ هُنَا", "segs": null, "full_uz": "Bu yerdan jo'na.", "note": null},
  {"num": 435, "time": "00:33:45,140 --> 00:34:02,660", "arabic": "أَخْشَى هَارُونَ رَشِيدَ لَمْ يَعُدْ كَسَابِقِ عَهْدِهِ", "segs": null, "full_uz": "Qo'rqamanki, Horun ar-Rashid ilgargidek emas endi.", "note": null},
  {"num": 436, "time": "00:34:02,660 --> 00:34:07,460", "arabic": "وَإِنَّنِي لَا أَلْمَحُ حِرْصَهُ شَدِيدًا عَلَى إِبْعَادِ وَلَدَيْهِ عَنْ كُلِّ مَا يَمُتُّ لِلْفُرْسِ بِصِلَةٍ", "segs": null, "full_uz": "Endi men uning ikkala o'g'lini forslarga aloqador narsalardan uzoqlashtirishga bo'lgan qattiq harakatini ko'rmayapman.", "note": null},
  {"num": 438, "time": "00:34:07,460 --> 00:34:15,840", "arabic": "إِنَّهُ يَنْتَقِي الشُّيُوخَ وَالْمُعَلِّمِينَ لَهُمَا مِنَ الْعَرَبِ الْأَقْحَاحِ دُونَ غَيْرِهِمْ", "segs": null, "full_uz": "U ularga faqat asl arablardan shayxlar va muallimlar tanlaydi.", "note": null},
  {"num": 440, "time": "00:34:15,840 --> 00:34:22,099", "arabic": "وَإِنْ كَانَ يَتَذَرَّعُ بِأَنَّهُ يُرِيدُ لَهُمَا لُغَةً عَرَبِيَّةً سَلِيمَةً", "segs": null, "full_uz": "Garchi u ular uchun sof arab tili xohlayman deb bahona qilsa ham.", "note": null},
  {"num": 441, "time": "00:34:22,099 --> 00:34:25,200", "arabic": "فَإِنَّ حُجَجَهُ وَهِيَ...", "segs": null, "full_uz": "Uning dalillari esa...", "note": null},
  {"num": 442, "time": "00:34:25,199 --> 00:34:30,460", "arabic": "رُبَّمَا يَظْفَرُ بِمَا يُرِيدُهُ مَعَ الْأَمِينِ بْنِ زُبَيْدَةَ إِذَا أُمُّهُ مِنْ عُيُونٍ عَرَبِيَّةٍ", "segs": null, "full_uz": "Balki xohlaganiga al-Amin ibn Zubayda bilan erishar, chunki uning onasi asl arab.", "note": null},
  {"num": 443, "time": "00:34:30,460 --> 00:34:39,399", "arabic": "أَمَّا ابْنُ أُخْتِنَا الْمَأْمُونُ أَبْقَاهُ اللَّهُ فَتِلْكَ الْمَسْأَلَةُ لَنْ يَنَالَ بُغْيَتَهُ مَعَ فَتًى تَجْرِي فِي عُرُوقِهِ دِمَاءُ أُمِّهِ الْفَارِسِيَّةِ", "segs": [{"ar": "أَمَّا ابْنُ أُخْتِنَا الْمَأْمُونُ أَبْقَاهُ اللَّهُ فَتِلْكَ الْمَسْأَلَةُ", "uz": "jiyanimiz Ma'mun bo'lsa, Alloh uni asrasin, u boshqa masala"}, {"ar": "لَنْ يَنَالَ بُغْيَتَهُ مَعَ فَتًى تَجْرِي فِي عُرُوقِهِ دِمَاءُ أُمِّهِ الْفَارِسِيَّةِ", "uz": "tomirida fors onasining qoni oqadigan yigit bilan maqsadiga yeta olmaydi"}], "full_uz": "Jiyanimiz Ma'mun bo'lsa, Alloh uni asrasin, u boshqa masala — tomirida fors onasining qoni oqadigan yigit bilan maqsadiga yeta olmaydi.", "note": null},
  {"num": 445, "time": "00:34:39,399 --> 00:34:45,319", "arabic": "إِنَّمَا خَشْيَتِي مِنَ الْمَأْمُونِ أَشَدُّ مِنْ خَشْيَتِي مِنَ الْأَمِينِ أَيُّهَا الْفَضْلُ", "segs": null, "full_uz": "Balki Ma'mundan qo'rqishim, Amindan qo'rqishimdan ko'ra kattaroq, ey Fadl.", "note": null},
  {"num": 446, "time": "00:34:45,319 --> 00:34:51,000", "arabic": "وَكَيْفَ ذَلِكَ يَا أَبِي وَالْمَأْمُونُ ابْنُ أُخْتِنَا وَمِنْ بَنِي جِلْدَتِنَا", "segs": null, "full_uz": "Qanday bo'lishi mumkin, otajon, Ma'mun bizning jiyanimiz-ku, o'zimizning qonimizdan.", "note": "«بَنُو جِلْدَتِنَا» — «bizning terimizdan bo'lganlar», ya'ni bir qavm, bir irqdan bo'lganlar ma'nosidagi ibora."},
  {"num": 448, "time": "00:34:52,719 --> 00:34:57,319", "arabic": "نَسِيتَ أَنَّ الْمَأْمُونَ نَفْسَهُ يُعَانِي مِنْ كَوْنِهِ ابْنَ جَارِيَةٍ فَارِسِيَّةٍ", "segs": null, "full_uz": "Ma'munning o'zi ham fors cho'risining o'g'li ekanidan aziyat chekayotganini unutding.", "note": null},
  {"num": 449, "time": "00:34:57,319 --> 00:35:03,919", "arabic": "وَهُوَ يَرَى حَظْوَةَ ابْنِ زُبَيْدَةَ الْأَمِينِ أَنَّهُ مِنْ بَنِي هَاشِمٍ وَالْعَرَبِ دُونَهُ", "segs": null, "full_uz": "U esa Zubayda o'g'li Aminni Bani Hoshim va arablardan biri sifatida ustunroq ko'radi.", "note": null},
  {"num": 451, "time": "00:35:03,919 --> 00:35:13,299", "arabic": "وَإِذَنْ يَا أَبِي، مَا أَخْشَاهُ أَنْ يَسْعَى الْمَأْمُونُ لِإِثْبَاتِ وَلَائِهِ لِنِصْفِهِ الْعَرَبِيِّ", "segs": null, "full_uz": "Unda, otajon, qo'rqadigan narsam — Ma'mun o'zining arab yarmiga sodiqligini isbotlashga urinishi.", "note": null},
  {"num": 454, "time": "00:35:13,299 --> 00:35:16,959", "arabic": "مُضَحِّيًا بِنَا نَحْنُ أَخْوَالَهُ الْفُرْسَ", "segs": null, "full_uz": "Bizni, uning fors tog'alarini, qurbon qilib.", "note": null},
  {"num": 455, "time": "00:35:16,959 --> 00:35:22,519", "arabic": "جِئْنَا نَبْحَثُ عَنْ حَلٍّ لِمُشْكِلَتِنَا عِنْدَ فَتًى غَارِقٍ فِي مَشَاكِلِهِ الْخَاصَّةِ", "segs": null, "full_uz": "Biz o'z muammolariga g'arq bo'lgan bir yigitdan muammomizga yechim izlab keldik.", "note": null},
  {"num": 457, "time": "00:35:25,759 --> 00:35:33,179", "arabic": "أَدْرَكْتُمْ مَكْمَنَ الْخَطَرِ يَا أَبْنَاءَ بَرْمَكَ؟", "segs": null, "full_uz": "Xavfning qayerda ekanini angladingizmi, Barmak o'g'illari?", "note": null},
  {"num": 458, "time": "00:35:33,179 --> 00:35:34,159", "arabic": "أَدْرَكْنَا يَا أَبِي", "segs": null, "full_uz": "Angladik, otajon.", "note": null},
  {"num": 459, "time": "00:35:34,159 --> 00:35:35,519", "arabic": "وَلَكِنْ مَا الْحَلُّ؟", "segs": null, "full_uz": "Lekin yechim nima?", "note": null},
  {"num": 460, "time": "00:35:38,259 --> 00:35:39,019", "arabic": "لَا تَقْلَقُوا", "segs": null, "full_uz": "Xavotir olmanglar.", "note": null},
  {"num": 461, "time": "00:35:39,019 --> 00:35:44,519", "arabic": "سَأَجِدُ حَلًّا", "segs": null, "full_uz": "Yechim topaman.", "note": null},
  {"num": 463, "time": "00:36:21,519 --> 00:36:22,980", "arabic": "هَلْ يَلْزَمُهُ كَعَامِلٍ؟", "segs": null, "full_uz": "Ishchi kerakmi?", "note": null},
  {"num": 464, "time": "00:36:22,980 --> 00:36:23,739", "arabic": "اِذْهَبْ مِنْ هُنَا", "segs": null, "full_uz": "Bu yerdan jo'na.", "note": null},
  {"num": 465, "time": "00:36:23,739 --> 00:36:38,280", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Sizga salom.", "note": null},
  {"num": 466, "time": "00:36:38,280 --> 00:36:40,059", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Sizga ham salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 467, "time": "00:36:40,059 --> 00:36:41,420", "arabic": "مَاذَا تُرِيدُ؟", "segs": null, "full_uz": "Nima kerak senga?", "note": null},
  {"num": 468, "time": "00:36:41,420 --> 00:36:42,219", "arabic": "أَبْحَثُ عَنْ عَمَلٍ", "segs": null, "full_uz": "Ish izlayapman.", "note": null},
  {"num": 469, "time": "00:36:42,219 --> 00:36:46,780", "arabic": "وَهَلْ تُجِيدُ صِنَاعَةَ الْقَرَابِيسِ وَالسُّرُوجِ؟", "segs": null, "full_uz": "Egar va uning qismlarini yasashni bilasanmi?", "note": null},
  {"num": 470, "time": "00:36:46,780 --> 00:36:47,059", "arabic": "لَا", "segs": null, "full_uz": "Yo'q.", "note": null},
  {"num": 471, "time": "00:36:47,059 --> 00:36:52,059", "arabic": "إِذَنِ اسْتَأْنِفْ بَحْثَكَ، فَلَا مَكَانَ هُنَا إِلَّا لِمُتْقِنٍ", "segs": null, "full_uz": "Unda qidiruvingni davom ettir, bu yerda faqat ustaga joy bor.", "note": null},
  {"num": 473, "time": "00:36:52,059 --> 00:37:02,079", "arabic": "فَقَدْ بَحَثْتُ فِي السُّوقِ كُلِّهَا وَلَمْ أَجِدْ عَمَلًا حَتَّى وَرِمَتْ قَدَمَايَ، أُرِيدُ أَنْ أَعْمَلَ عِنْدَكَ", "segs": [{"ar": "فَقَدْ بَحَثْتُ فِي السُّوقِ كُلِّهَا وَلَمْ أَجِدْ عَمَلًا حَتَّى وَرِمَتْ قَدَمَايَ", "uz": "butun bozorni kezib chiqdim, oyoqlarim shishguncha, lekin ish topolmadim"}, {"ar": "أُرِيدُ أَنْ أَعْمَلَ عِنْدَكَ", "uz": "sizda ishlashni istayman"}], "full_uz": "Butun bozorni kezib chiqdim, oyoqlarim shishguncha, lekin ish topolmadim. Sizda ishlashni istayman.", "note": null},
  {"num": 475, "time": "00:37:02,079 --> 00:37:06,199", "arabic": "وَمَاذَا أَصْنَعُ بِكَ إِنْ لَمْ تُحْسِنْ صَنْعَتَنَا؟", "segs": null, "full_uz": "Agar hunarimizni bilmasang, seni nima qilardim?", "note": null},
  {"num": 476, "time": "00:37:06,199 --> 00:37:08,940", "arabic": "وَهَلْ يُولَدُ جَمِيعُ النَّاسِ وَهُمْ يُحْسِنُونَ مَا يَصْنَعُونَ؟", "segs": null, "full_uz": "Hamma odam o'z ishini bilib tug'iladimi?", "note": null},
  {"num": 477, "time": "00:37:08,940 --> 00:37:11,780", "arabic": "أَرْجُوكَ، سَأُتْقِنُ صَنْعَةً بِسُرْعَةٍ", "segs": null, "full_uz": "Iltimos, hunarni tez o'rganib olaman.", "note": null},
  {"num": 478, "time": "00:37:11,780 --> 00:37:18,840", "arabic": "إِنَّمَا أُرِيدُ أَجِيرًا يُسَاعِدُنِي لَا أُسَاعِدُهُ، وَأَنَا ذَلِكَ الْأَجِيرُ", "segs": null, "full_uz": "Menga o'zimga yordam beradigan yollanma kerak, unga yordam beradigan emas. Men aynan o'sha yollanmaman.", "note": "Ustaning gapida qarama-qarshilik: «yordam beradigan» va «yordam olishga muhtoj» ma'nolarini o'ynash orqali ish talabgorining foydasizligini ta'kidlaydi."},
  {"num": 480, "time": "00:37:18,840 --> 00:37:24,000", "arabic": "لَسْنَا فِي بِضْعَةِ أَيَّامٍ فَقَطْ، لَا وَقْتَ لَدَيَّ أُضَيِّعُهُ مَعَكَ", "segs": null, "full_uz": "Bu bir necha kunlik ish emas, senga sarflaydigan vaqtim yo'q.", "note": null},
  {"num": 482, "time": "00:37:24,000 --> 00:37:26,019", "arabic": "اِذْهَبْ وَابْحَثْ عَنْ عَمَلٍ فِي مَكَانٍ آخَرَ", "segs": null, "full_uz": "Boshqa joydan ish izla.", "note": null},
  {"num": 483, "time": "00:37:26,019 --> 00:37:33,760", "arabic": "سَيِّدِي أَرْجُوكَ لَا تَكِدْ خَاطِرِي، أَنَا أُعِيلُ أُمِّي، وَمُنْذُ أَيَّامٍ أَبْحَثُ عَنْ عَمَلٍ جَاهِدًا وَلَمْ أَجِدْ", "segs": [{"ar": "سَيِّدِي أَرْجُوكَ لَا تَكِدْ خَاطِرِي", "uz": "hazratim, iltimos, ko'nglimni og'ritmang"}, {"ar": "أَنَا أُعِيلُ أُمِّي، وَمُنْذُ أَيَّامٍ أَبْحَثُ عَنْ عَمَلٍ جَاهِدًا وَلَمْ أَجِدْ", "uz": "men onamni boqaman, va necha kundan beri jon-jahdim bilan ish qidiryapman, topolmayapman"}], "full_uz": "Hazratim, iltimos, ko'nglimni og'ritmang — men onamni boqaman, va necha kundan beri jon-jahdim bilan ish qidiryapman, topolmayapman.", "note": "«لَا تَكِدْ خَاطِرِي» — «ko'nglimni og'ritma, meni ranjitma» ma'nosidagi ibora."},
  {"num": 485, "time": "00:37:35,880 --> 00:37:38,480", "arabic": "لَا تُعِنْ عَلَيَّ نَوَائِبَ دَهْرِي", "segs": null, "full_uz": "Zamonamning kulfatlariga qarshi menga yordamchi bo'lma.", "note": null},
  {"num": 486, "time": "00:37:38,480 --> 00:37:39,980", "arabic": "كَمْ أَنْتَ لَحُوحٌ يَا فَتَى", "segs": null, "full_uz": "Naqadar qattiq talab qilasan, yigit.", "note": null},
  {"num": 487, "time": "00:37:39,980 --> 00:37:41,740", "arabic": "أَرْجُوكَ", "segs": null, "full_uz": "Iltimos.", "note": null},
  {"num": 488, "time": "00:37:41,740 --> 00:37:46,300", "arabic": "حَسَنًا", "segs": null, "full_uz": "Yaxshi, xo'p.", "note": null},
  {"num": 489, "time": "00:37:46,300 --> 00:37:51,800", "arabic": "وَلَكِنْ سَأَضَعُكَ قَيْدَ الِاخْتِبَارِ لِأَيَّامٍ مَعْدُودَاتٍ، فَإِنْ رَأَيْتُ مِنْكَ جِدًّا وَأَمَانَةً وَحِرْصًا عَلَى الْعَمَلِ", "segs": [{"ar": "وَلَكِنْ سَأَضَعُكَ قَيْدَ الِاخْتِبَارِ لِأَيَّامٍ مَعْدُودَاتٍ", "uz": "lekin seni bir necha kunlik sinovga qo'yaman"}, {"ar": "فَإِنْ رَأَيْتُ مِنْكَ جِدًّا وَأَمَانَةً وَحِرْصًا عَلَى الْعَمَلِ", "uz": "agar sendan jiddiylik, halollik va ishga qattiq intilish ko'rsam"}], "full_uz": "Lekin seni bir necha kunlik sinovga qo'yaman — agar sendan jiddiylik, halollik va ishga qattiq intilish ko'rsam...", "note": null},
  {"num": 491, "time": "00:37:51,800 --> 00:37:54,100", "arabic": "وَإِلَّا طَرَحْتُكَ أَرْضًا كَمَا جِئْتَ", "segs": null, "full_uz": "Aks holda, kelganingdek seni yerga tashlayman (haydab yuboraman).", "note": null},
  {"num": 492, "time": "00:37:54,100 --> 00:37:57,880", "arabic": "وَعْدًا مِنِّي، سَتَجِدُنِي أَفْضَلَ مِمَّا تَطْلُبُ", "segs": null, "full_uz": "Va'da beraman, meni talabingizdan ham a'lo topasiz.", "note": null},
  {"num": 493, "time": "00:37:57,880 --> 00:38:00,280", "arabic": "اَلْفِعْلُ أَبْقَى مِنْ لَحْنِ الْقَوْلِ يَا فَتَى", "segs": null, "full_uz": "Amal — chiroyli so'zdan ko'ra ko'proq qoladi, yigit.", "note": "«الفعل أبقى من لحن القول» — «amal go'zal so'zdan ko'ra uzoqroq qoladi» mazmunidagi hikmatli gap: so'zdan ko'ra ish muhimroq."},
  {"num": 495, "time": "00:38:00,280 --> 00:38:08,760", "arabic": "هَيَّا شَمِّرْ عَنْ سَاعِدَيْكَ وَاذْهَبْ إِلَى فُرْنِ الْفَوَّالِ وَآتِنَا غَدَاءَنَا", "segs": null, "full_uz": "Yenglaringni shimarib, loviyachi do'koniga bor va tushlikimizni olib kel.", "note": "«شَمَّرَ عَنْ سَاعِدَيْهِ» — «yenglarini shimarmoq», ya'ni ishga jiddiy kirishmoq ma'nosidagi ibora."},
  {"num": 496, "time": "00:38:08,760 --> 00:38:13,720", "arabic": "خُذْ هَذَا رُبُعَ دِرْهَمٍ لِلْفُولِ وَمِثْلَهُ لِلْخُبْزِ وَلَا تَتَأَخَّرْ", "segs": null, "full_uz": "Mana, loviyaga chorak dirham, xuddi shuncha nonga, va kechikma.", "note": null},
  {"num": 497, "time": "00:38:13,720 --> 00:38:15,100", "arabic": "عَلَى جَنَاحَيْنِ يَا عَمَّاهُ", "segs": null, "full_uz": "Uchib boraman-u, kelaman, amakijon.", "note": "«عَلَى جَنَاحَيْنِ» — «ikki qanotda», ya'ni juda tez ma'nosidagi majoziy ibora."},
  {"num": 498, "time": "00:38:15,100 --> 00:38:16,240", "arabic": "اِنْتَظِرْ", "segs": null, "full_uz": "Kut.", "note": null},
  {"num": 499, "time": "00:38:16,239 --> 00:38:18,559", "arabic": "مَاذَا؟ مَا اسْمُهُ؟", "segs": null, "full_uz": "Nima? Ismi nima uning?", "note": null},
  {"num": 500, "time": "00:38:18,559 --> 00:38:20,419", "arabic": "فَرَجٌ، اسْمِي فَرَجٌ", "segs": null, "full_uz": "Faraj, ismim Faraj.", "note": null},
  {"num": 502, "time": "00:38:20,419 --> 00:38:22,539", "arabic": "لَكَ مِنِ اسْمِكَ حَظٌّ وَنَصِيبٌ", "segs": null, "full_uz": "Isming senga baxt va nasiba keltirsin.", "note": "«فَرَجٌ» ismi «yengillik, najot» ma'nosini bildiradi — bu satrda so'z o'yini bor."},
  {"num": 503, "time": "00:38:22,539 --> 00:38:26,799", "arabic": "اِنْتَظِرْ، خُذْ، خُذْ هَذَا الصَّحْنَ مَعَكَ", "segs": null, "full_uz": "Kut, ol, bu likobchani ham olib ket.", "note": null},
  {"num": 505, "time": "00:38:26,799 --> 00:38:37,239", "arabic": "وَمَاذَا لَوْ أَنَّ الْفَتَى رَاوَدَتْهُ نَفْسُهُ عَلَى سَرِقَةِ الصَّحْنِ وَالنُّقُودِ؟", "segs": null, "full_uz": "Agar yigitning ko'ngli likobcha va pulni o'g'irlashga qo'zg'alsa-chi?", "note": "«رَاوَدَتْهُ نَفْسُهُ» — «nafsi uni vasvasaga soldi», ya'ni ichki his-tuyg'usi yomon ishga undadi ma'nosidagi ibora."},
  {"num": 506, "time": "00:38:37,239 --> 00:38:47,019", "arabic": "مَا كَانَ يَجِبُ أَنْ أَرْضَى بِذَهَابِهِ مَعَ عَمِّهِ إِسْحَاقَ إِلَى الْوَالِي، فَلَوْ أَصَابَهُ مَكْرُوهٌ لَنْ أُسَامِحَ نَفْسِي", "segs": [{"ar": "مَا كَانَ يَجِبُ أَنْ أَرْضَى بِذَهَابِهِ مَعَ عَمِّهِ إِسْحَاقَ إِلَى الْوَالِي", "uz": "amakisi Ishoq bilan voliy huzuriga borishiga rozi bo'lmasligim kerak edi"}, {"ar": "فَلَوْ أَصَابَهُ مَكْرُوهٌ لَنْ أُسَامِحَ نَفْسِي", "uz": "agar unga biror yomonlik yetsa, o'zimni kechirmayman"}], "full_uz": "Amakisi Ishoq bilan voliy huzuriga borishiga rozi bo'lmasligim kerak edi — agar unga biror yomonlik yetsa, o'zimni kechirmayman.", "note": null},
  {"num": 508, "time": "00:38:52,099 --> 00:39:03,699", "arabic": "وَلَكِنْ مَا الَّذِي فَعَلَهُ حَتَّى يُعَاقَبَ عَلَيْهِ؟ كُلُّ مَا قَامَ بِهِ أَنَّهُ تَخَلَّصَ مِنْ كِتَابٍ اعْتَقَدَ أَنَّ فِيهِ أَذًى لِلنَّاسِ", "segs": [{"ar": "وَلَكِنْ مَا الَّذِي فَعَلَهُ حَتَّى يُعَاقَبَ عَلَيْهِ؟", "uz": "lekin u jazolanishi uchun nima qilibdi?"}, {"ar": "كُلُّ مَا قَامَ بِهِ أَنَّهُ تَخَلَّصَ مِنْ كِتَابٍ اعْتَقَدَ أَنَّ فِيهِ أَذًى لِلنَّاسِ", "uz": "u faqat odamlarga zarar bor deb o'ylagan bir maktubdan xalos bo'ldi, xolos"}], "full_uz": "Lekin u jazolanishi uchun nima qilibdi? U faqat odamlarga zarar bor deb o'ylagan bir maktubdan xalos bo'ldi, xolos.", "note": null},
  {"num": 510, "time": "00:39:03,699 --> 00:39:09,379", "arabic": "أُقْسِمُ إِنْ أَصَابَهُمْ مَكْرُوهٌ فَسَيَرَوْنَ مِنِّي مَا لَا يَتَصَوَّرُونَ", "segs": null, "full_uz": "Qasam ichamanki, agar ularga biror yomonlik yetsa, mendan kutmagan narsalarini ko'radilar.", "note": null},
  {"num": 512, "time": "00:39:09,379 --> 00:39:14,139", "arabic": "سَأَصْبِرُ بَعْضَ الْوَقْتِ وَبَعْدَهَا سَأَرَى مَا سَأَفْعَلُ", "segs": null, "full_uz": "Bir muddat sabr qilaman, keyin nima qilishimni ko'raman.", "note": null},
  {"num": 514, "time": "00:39:14,139 --> 00:39:31,399", "arabic": "هَيَّا يَا سَيِّدِي", "segs": null, "full_uz": "Marhamat, hazratim.", "note": null},
  {"num": 515, "time": "00:39:31,399 --> 00:39:32,939", "arabic": "إِنَّهُمَا سَاخِنَانِ", "segs": null, "full_uz": "Ikkalasi ham issiq.", "note": null},
  {"num": 516, "time": "00:39:32,940 --> 00:39:37,539", "arabic": "إِنَّهُمَا سَاخِنَانِ حَقًّا", "segs": null, "full_uz": "Rostdan ham juda issiq ekan.", "note": null},
  {"num": 517, "time": "00:39:37,539 --> 00:39:41,360", "arabic": "اِجْلِسْ وَشَارِكْ مُعَلِّمَكَ طَعَامَكَ", "segs": null, "full_uz": "O'tir va ovqatingni ustozing bilan bo'lish.", "note": null},
  {"num": 518, "time": "00:39:41,360 --> 00:39:41,780", "arabic": "حَسَنًا", "segs": null, "full_uz": "Xo'p.", "note": null},
  {"num": 519, "time": "00:39:41,780 --> 00:39:49,539", "arabic": "لَقَدْ أَثْبَتَّ لِي يَا فَرَجُ أَنَّكَ أَمِينٌ وَنَشِيطٌ، وَسَنَرَى حَمَاسَكَ لِلْعَمَلِ بَعْدَ الطَّعَامِ", "segs": null, "full_uz": "Faraj, senga ishonchli va faol ekanligingni isbotladim — ishga bo'lgan g'ayratingni ovqatdan keyin ko'ramiz.", "note": null},
  {"num": 521, "time": "00:39:49,539 --> 00:39:51,039", "arabic": "حَسَنًا، تَفَضَّلْ", "segs": null, "full_uz": "Xo'p, marhamat.", "note": null},
  {"num": 523, "time": "00:39:51,039 --> 00:39:55,860", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Sizga salom.", "note": null},
  {"num": 524, "time": "00:39:55,860 --> 00:39:57,659", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Sizga ham salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 525, "time": "00:39:57,659 --> 00:40:01,860", "arabic": "مَاذَا جَرَى مَعَكَ عِنْدَ الْوَالِي؟", "segs": null, "full_uz": "Voliy huzurida senga nima bo'ldi?", "note": null},
  {"num": 526, "time": "00:40:01,860 --> 00:40:04,780", "arabic": "لَمْ يَجْرِ الْكَثِيرُ، لَقَدْ تَرَكْتُ الْعَمَلَ فِي بَيْتِ الْحِكْمَةِ", "segs": null, "full_uz": "Ko'p narsa bo'lmadi, Baytul-Hikmadagi ishimni tashlab qo'ydim.", "note": null},
  {"num": 528, "time": "00:40:04,780 --> 00:40:10,960", "arabic": "لَمْ تُخْبِرْنِي، مَا الَّذِي حَدَثَ بَيْنَكَ وَبَيْنَ الْوَالِي؟", "segs": null, "full_uz": "Menga aytmagansan-ku, sen bilan voliy o'rtasida nima bo'ldi?", "note": null},
  {"num": 530, "time": "00:40:10,960 --> 00:40:21,980", "arabic": "لَيْسَ مُهِمًّا مَا حَدَثَ بَيْنَنَا يَا أُمِّي، اَلْمُهِمُّ أَنَّنِي تَرَكْتُ عَمَلًا كَانَ عَوْنًا لَنَا بَعْدَ اللَّهِ عَزَّ وَجَلَّ، وَالْآنَ يَجِبُ أَنْ أَبْحَثَ عَنْ عَمَلٍ مِنْ جَدِيدٍ", "segs": [{"ar": "لَيْسَ مُهِمًّا مَا حَدَثَ بَيْنَنَا يَا أُمِّي", "uz": "oramizda nima bo'lgani muhim emas, onajon"}, {"ar": "اَلْمُهِمُّ أَنَّنِي تَرَكْتُ عَمَلًا كَانَ عَوْنًا لَنَا بَعْدَ اللَّهِ عَزَّ وَجَلَّ", "uz": "muhimi — Allohdan keyin bizga yordamchi bo'lgan ishni tashlab qo'ydim"}, {"ar": "وَالْآنَ يَجِبُ أَنْ أَبْحَثَ عَنْ عَمَلٍ مِنْ جَدِيدٍ", "uz": "va endi yangidan ish izlashim kerak"}], "full_uz": "Oramizda nima bo'lgani muhim emas, onajon. Muhimi — Allohdan keyin bizga yordamchi bo'lgan ishni tashlab qo'ydim, va endi yangidan ish izlashim kerak.", "note": null},
  {"num": 533, "time": "00:40:21,980 --> 00:40:25,920", "arabic": "أَهَذَا مَا يَجْعَلُكَ جَهْمَ الْوَجْهِ؟ أَوْ أَشَدَّ مِنْ ذَلِكَ يَا أُمِّي", "segs": null, "full_uz": "Yuzingni bunday ekshigan qiladigan sababmi bu? Yoki bundan ham og'irroq narsa, onajon.", "note": null},
  {"num": 535, "time": "00:40:25,920 --> 00:40:33,219", "arabic": "أَرْعَبْتَنِي يَا وَلَدِي بِدُخُولِكَ عَلَيَّ وَأَنْتَ عَلَى هَذِهِ الْحَالِ، حَتَّى أَنَّنِي خِلْتُ أَنَّ الْوَالِيَ قَدْ نَالَكَ بِمَسَاءَةٍ", "segs": null, "full_uz": "Bunday holda kirib kelganingda meni juda qo'rqitding, hatto voliy senga yomonlik qilgan deb o'ylab qoldim.", "note": null},
  {"num": 537, "time": "00:40:33,219 --> 00:40:39,800", "arabic": "أَمَّا مَا تَخْشَاهُ يَا وَلَدِي فَهُوَ أَهْوَنُ بِكَثِيرٍ مِنْ هَذَا الْقَلَقِ", "segs": null, "full_uz": "Sen qo'rqqan narsa esa bu tashvishdan ancha yengilroq, o'g'lim.", "note": null},
  {"num": 539, "time": "00:40:39,800 --> 00:40:46,539", "arabic": "اِسْمَعْ يَا بُنَيَّ، قَدْ عِشْنَا قَبْلَ عَمَلِكَ وَسَوْفَ نَعِيشُ بَعْدَهُ بِإِذْنِ اللَّهِ", "segs": null, "full_uz": "Eshit, o'g'lim, biz sening ishingdan oldin ham yashaganmiz, undan keyin ham Alloh izni bilan yashayveramiz.", "note": null},
  {"num": 542, "time": "00:40:46,539 --> 00:40:48,320", "arabic": "وَمِنْ أَيْنَ النَّفَقَةُ يَا أُمِّي؟", "segs": null, "full_uz": "Xarajatlarni qayerdan topamiz, onajon?", "note": null},
  {"num": 543, "time": "00:40:48,320 --> 00:40:50,980", "arabic": "اِسْمَعْ يَا وَلَدِي، مُذْ كُنْتَ صَغِيرًا", "segs": null, "full_uz": "Eshit, o'g'lim, sen kichkina paytingdanoq.", "note": null},
  {"num": 545, "time": "00:40:51,659 --> 00:40:55,980", "arabic": "وَأَنَا أَحْرِصُ عَلَى أَنْ تَبْلُغَ غَايَتَكَ وَتُدْرِكَ حَاجَتَكَ", "segs": null, "full_uz": "Men sening maqsadingga yetishing va ehtiyojingni qondirishingga astoydil harakat qilib kelaman.", "note": null},
  {"num": 547, "time": "00:40:55,980 --> 00:41:00,800", "arabic": "وَأَنَا وَأَنْتَ نَعْلَمُ جَيِّدًا بِأَنَّكَ لَنْ تَصِلَ إِلَى مَا تَصْبُو إِلَيْهِ إِلَّا مِنْ خِلَالِ حَلَقَاتِ دَرْسِكَ عِنْدَ شَيْخِكَ", "segs": null, "full_uz": "Men ham, sen ham yaxshi bilamiz — faqat shayxing huzuridagi darslaring orqaligina intilgan narsangga yetasan.", "note": null},
  {"num": 549, "time": "00:41:03,780 --> 00:41:09,699", "arabic": "فَاعْمَلْ يَا بُنَيَّ عَلَى أَلَّا تَدَعَ شَيْئًا يَصْرِفُكَ عَنْ تَحْقِيقِ حُلْمِكَ", "segs": null, "full_uz": "Shu sababdan, o'g'lim, orzuingga erishishdan hech narsa seni chalg'itmasin.", "note": null},
  {"num": 551, "time": "00:41:09,699 --> 00:41:17,199", "arabic": "وَأَنَا لَنْ آلُوَ جُهْدًا حَتَّى أَرَاكَ عَلَمًا مِنْ أَعْلَامِ هَذِهِ الْأُمَّةِ", "segs": null, "full_uz": "Va men seni shu ummatning ulug'laridan biri sifatida ko'rgunimcha hech qanday sa'y-harakatimni ayamayman.", "note": null},
  {"num": 553, "time": "00:41:24,799 --> 00:41:30,839", "arabic": "ثُمَّ...", "segs": null, "full_uz": "So'ngra...", "note": null},
  {"num": 554, "time": "00:41:30,839 --> 00:41:32,019", "arabic": "لِمَاذَا هَذَا الْقَلَقُ عَلَى نَفَقَةِ مَعِيشَتِنَا؟", "segs": null, "full_uz": "Turmush xarajatlarimiz haqida bu qadar nega tashvishlanasan?", "note": null},
  {"num": 555, "time": "00:41:32,019 --> 00:41:37,519", "arabic": "لَدَيْنَا كِرَاءُ الدُّكَّانِ وَهُوَ يَسُدُّ حَاجَتَنَا إِنِ اقْتَصَدْنَا", "segs": null, "full_uz": "Bizda do'kon ijarasi bor, tejab-tergab ishlatsak, ehtiyojimizni qopladi.", "note": null},
  {"num": 557, "time": "00:41:37,519 --> 00:41:39,679", "arabic": "وَلَكِنْ يَا أُمِّي، كَفَاكَ عِنَادًا أَيُّهَا الْفَتَى الشَّيْخُ", "segs": null, "full_uz": "Lekin, onajon... Bas endi qaysarlik qilma, ey yosh-u qari yigit.", "note": "«الفتى الشيخ» — «yosh-qari yigit» — yoshiga qaramay katta odamlardek dono, vazmin xulq ko'rsatayotgan kishiga hazil aralash aytiladigan ibora."},
  {"num": 559, "time": "00:41:39,679 --> 00:41:46,219", "arabic": "لَنْ تَعُودَ لِلْعَمَلِ مَرَّةً أُخْرَى، وَسَيَخْلُو وَقْتُكَ لِدَرْسِكَ", "segs": null, "full_uz": "Ishga qayta bormaysan, va vaqting darsing uchun bo'shab qoladi.", "note": null},
  {"num": 561, "time": "00:41:46,219 --> 00:41:55,039", "arabic": "وَلَنْ أَعُودَ لِمُنَاقَشَتِكَ فِي هَذَا الْأَمْرِ مَرَّةً ثَانِيَةً، عِلْمُكَ هُوَ الْأَهَمُّ وَالْأَبْقَى", "segs": null, "full_uz": "Va bu masalada sening bilan qayta bahslashmayman, ilming eng muhim va eng qolguvchi narsadir.", "note": null},
];

if (typeof module !== "undefined" && module.exports) {
  module.exports = lessons;
}